(window.NTDATA=window.NTDATA||{});(NTDATA.cass=NTDATA.cass||{}).mt={"1":{"1":"Книга о рождении Иисуса Христа, сына Давидова,\nсына Авраамова.","2":"Авраам родил Исаака; Исаак родил Иакова; Иаков\nродил Иуду и братьев его;","3":"Иуда родил Фареса и Зару от Фамари; Фарес\nродил Есрома; Есром родил Арама;","4":"Арам родил Аминадава; Аминадав родил Наасона;\nНаасон родил Салмона;","5":"Салмон родил Вооза от Рахавы; Вооз родил Овида\nот Руфи; Овид родил Иессея;","6":"Иессей родил Давида царя; Давид родил Соломона\nот бывшей за Урией;","7":"Соломон родил Ровоама; Ровоам родил Авию; Авия\nродил Асу;","8":"Аса родил Иосафата; Иосафат родил Иорама;\nИорам родил Озию;","9":"Озия родил Иоафама; Иоафам родил Ахаза; Ахаз\nродил Езекию;","10":"Езекия родил Манассию; Манассия родил Амона;\nАмон родил Иосию;","11":"Иосия родил Иехонию и братьев его, во время\nпереселения в Вавилон.","12":"По переселении же в Вавилон Иехония родил\nСалафиила; Салафиил родил Зоровавеля;","13":"Зоровавель\nродил\nАвиуда;\nАвиуд\nродил\nЕлиакима; Елиаким родил Азора;","14":"Азор родил Садока; Садок родил Ахима; Ахим\nродил Елиуда;","15":"Елиуд родил Елеазара; Елеазар родил Матфана;\nМатфан родил Иакова;","16":"Иаков родил Иосифа, мужа Марии, от Которой\nродился Иисус, называемый Христос.","17":"Итак,\nвсех\nродов\nот\nАвраама\nдо\nДавида\nчетырнадцать родов; и от Давида до переселения в\nВавилон четырнадцать родов; и от переселения в\nВавилон до Христа четырнадцать родов.","18":"Рождение же Иисуса Христа было так: по\nобручении Матери Его Марии с Иосифом, прежде чем\nсочетались они, оказалось, что Она имеет во чреве от\nДуха Святого.","19":"Иосиф же, муж Ее, будучи праведен и не желая\nЕе обесславить, решил тайно отпустить Ее.","20":"Но когда он помыслил это, – вот, ангел Господень\nявился ему в сновидении и сказал: Иосиф, сын Давидов,\nне бойся принять Мариам, жену твою, ибо рожденное в\nНей – от Духа Святого.","21":"И родит Она Сына, и наречёшь имя Ему: Иисус,\nибо Он спасет народ Свой от грехов их.","22":"А\nэто\nвсё\nпроизошло,\nчтобы\nисполнилось\nсказанное Господом чрез пророка:","23":"Вот, Дева зачнет во чреве и родит Сына, и\nнарекут имя Ему: Еммануил, что в переводе значит: с\nнами Бог.","24":"Пробудившись от сна, Иосиф поступил, как\nповелел ему ангел Господень, и принял жену свою.","25":"И не знал Ее, доколе не родила Она Сына, и он\nнарек имя Ему: Иисус."},"2":{"1":"Когда же Иисус родился в Вифлееме Иудейском во\nдни Ирода царя, вот, волхвы с востока прибыли в\nИерусалим и сказали:","2":"где родившийся Царь Иудейский? Ибо мы видели\nвосход Его звезды и пришли поклониться Ему.","3":"Услышав это, царь Ирод смутился, и весь\nИерусалим с ним.","4":"И собрав всех первосвященников и книжников\nнародных, спрашивал у них: где родится Христос?","5":"Они же сказали ему: в Вифлееме Иудейском, ибо\nтак написано чрез пророка:","6":"«И ты, Вифлеем, земля Иудина, ничем не меньше\nправителей Иудиных; ибо из тебя выйдет Вождь,\nКоторый будет пасти народ Мой, Израиля».","7":"Тогда Ирод, тайно призвав волхвов, точно выведал\nот них время, в продолжение которого являлась звезда.","8":"И послав их в Вифлеем, сказал: пойдите и всё\nточно узнайте о Младенце и, как только найдете Его,\nвозвестите мне, дабы и я пришел и поклонился Ему.","9":"Они же, послушавшись царя, пошли. И вот, звезда,\nвосход которой они видели, шла перед ними, доколе не\nпришла и не стала над местом, где был Младенец.","10":"Увидев звезду, они возрадовались радостью\nвесьма великою.","11":"И войдя в дом, увидели Младенца с Марией,\nМатерью Его, и павши поклонились Ему; и открыв\nсокровища свои, принесли Ему дары: золото, ладан и\nсмирну.","12":"И\nполучив\nоткровение\nв\nсновидении\nне\nвозвращаться к Ироду, иным путем удалились в страну\nсвою.","13":"Когда же они удалились, – вот, ангел Господень\nявляется в сновидении Иосифу и говорит: встань,\nвозьми Младенца и Матерь Его и беги в Египет, и будь\nтам, доколе не скажу тебе; ибо Ирод вскоре будет\nискать Младенца, чтобы погубить Его.","14":"И он встал, взял Младенца и Матерь Его ночью и\nудалился в Египет;","15":"и был там до кончины Ирода, чтобы исполнилось\nсказанное Господом чрез пророка: Из Египта призвал Я\nСына Моего.","16":"Тогда Ирод, увидев, что он обманут волхвами,\nвесьма разгневался и послал истребить всех младенцев\nв Вифлееме и во всей области его, от двух лет и ниже,\nпо времени, которое точно выведал от волхвов.","17":"Тогда исполнилось сказанное чрез Иеремию\nпророка:","18":"Голос в Раме был слышен, плач и вопль великий;\nРахиль плачет о детях своих: и не хочет она утешиться,\nпотому что их нет.","19":"А когда скончался Ирод, вот, ангел Господень\nявляется в сновидении Иосифу в Египте","20":"и говорит: встань, возьми Младенца и Матерь Его\nи иди в землю Израилеву, ибо умерли искавшие души\nМладенца.","21":"И он встал, взял Младенца и Матерь Его и вошел\nв землю Израилеву.","22":"Услышав же, что Архелай царствует над Иудеей,\nвместо отца своего Ирода, убоялся туда идти; получив\nже откровение в сновидении, удалился в пределы\nГалилейские.","23":"И\nпридя,\nпоселился\nв\nгороде,\nименуемом\nНазарет, дабы исполнилось сказанное чрез пророков,\nчто Он будет назван Назореем."},"3":{"1":"В те дни в пустыне Иудейской выходит на\nпроповедь Иоанн Креститель","2":"и говорит: кайтесь, ибо близко Царство Небесное,","3":"Он тот, о ком сказано чрез Исаию пророка: Голос\nвопиющего в пустыне: «приготовьте дорогу Господу,\nпрямыми делайте пути Его».","4":"У самого же Иоанна одежда была из верблюжьего\nволоса и пояс кожаный на бедрах его; и пищей его были\nсаранча и дикий мед.","5":"Тогда выходили к нему Иерусалим и вся Иудея и\nвся округа Иорданская.","6":"И крестились у него в Иордане реке, исповедуя\nгрехи свои.","7":"Увидев же, что многие из фарисеев и саддукеев\nидут к нему креститься, он сказал им: отродье змеиное,\nкто указал вам бежать от будущего гнева?","8":"Сотворите же плод, достойный покаяния.","9":"И не думайте говорить самим себе: «отец у нас\nАвраам», ибо говорю вам, что может Бог из камней этих\nвоздвигнуть детей Аврааму.","10":"Уже лежит топор при корне деревьев: итак,\nвсякое\nдерево,\nне\nприносящее\nдоброго\nплода,\nсрубается и бросается в огонь.","11":"Я вас крещу водою в покаяние, но Идущий за\nмною сильнее меня, Тот, Чью обувь я недостоин\nпонести. Он будет крестить вас Духом Святым и огнем.","12":"Лопата Его в руке Его, и Он очистит гумно Свое и\nсоберет пшеницу Свою в житницу, а мякину сожжет\nогнем неугасимым.","13":"Тогда приходит Иисус из Галилеи на Иордан к\nИоанну креститься от него.","14":"Иоанн же препятствовал Ему, говоря: мне нужно\nкреститься от Тебя, а Ты приходишь ко мне?","15":"Но Иисус ответил ему: допусти сейчас; ибо так\nподобает нам исполнить всякую правду. Тогда он\nдопустил Его.","16":"И крестившись, Иисус тотчас вышел из воды; и\nвот, открылись небеса, и увидел Он нисходящего, как\nголубь, Духа Божия, спускающегося на Него.","17":"И вот, голос с небес, говорящий: это Сын Мой\nВозлюбленный, на Ком Мое благоволение."},"4":{"1":"Тогда Иисус был возведен Духом в пустыню для\nискушения от диавола.","2":"И проведя в посте сорок дней и сорок ночей,\nнаконец ощутил голод,","3":"И подойдя, искуситель сказал Ему: если Ты Сын\nБожий, скажи, чтобы камни эти сделались хлебами.","4":"Он же ответил: написано: «Не хлебом одним жив\nбудет человек, но всяким словом, исходящим из уст\nБожиих».","5":"Тогда берет Его диавол в святой город и ставит\nЕго на крыло храма,","6":"и говорит Ему: если Ты Сын Божий, бросься вниз;\nнаписано, ведь: «Ангелам Своим заповедует Он о Тебе»,\nи: «На руках понесут Тебя, чтобы Ты не преткнулся о\nкамень ногою Твоею».","7":"Сказал ему Иисус: написано также: «Не искушай\nГоспода Бога твоего».","8":"Снова берет Его диавол на гору весьма высокую и\nпоказывает Ему все царства мира и славу их,","9":"и говорит Ему: всё это дам Тебе, если павши\nпоклонишься мне.","10":"Тогда\nговорит\nему\nИисус:\nпрочь,\nсатана;\nнаписано: «Господу Богу твоему поклоняйся и Ему\nодному служи».","11":"Тогда оставляет Его диавол, – и вот, ангелы\nприступили и служили Ему.","12":"Услышав же, что Иоанн предан, Он удалился в\nГалилею.","13":"И оставив Назарет, пришел и поселился в\nКапернауме приморском, в области Завулоновой и\nНеффалимовой,","14":"чтобы\nисполнилось\nсказанное\nчрез\nИсаию\nпророка:","15":"Земля Завулонова и земля Неффалимова на пути\nморском, за Иорданом, Галилея язычников,","16":"народ, сидящий во тьме, увидел свет великий, и\nсидящим в стране и тени смерти, свет воссиял им.","17":"С того времени начал Иисус проповедовать и\nговорить: кайтесь, ибо близко Царство Небесное.","18":"Проходя же по берегу моря Галилейского, Он\nувидел двух братьев, Симона, называемого Петром, и\nАндрея, брата его, закидывающих сеть в море, ибо они\nбыли рыболовы.","19":"И говорит им: идите за Мною, и Я сделаю вас\nловцами людей.","20":"И они тотчас оставили сети и последовали за\nНим.","21":"И пройдя оттуда дальше, увидел Он других двух\nбратьев, Иакова Зеведеева и Иоанна, брата его, в лодке\nс Зеведеем, отцом их, чинящих сети свои, и призвал их.","22":"Они же тотчас оставили лодку и отца своего и\nпоследовали за Ним.","23":"И ходил Иисус по всей Галилее, уча в синагогах\nих и проповедуя Евангелие Царства и исцеляя всякую\nболезнь и всякую немощь в народе.","24":"И прошел слух о Нем по всей Сирии; и привели к\nНему\nвсех\nнедужных,\nодержимых\nразличными\nболезнями и муками, и бесноватых, и лунатиков, и\nрасслабленных, и Он исцелил их.","25":"И последовало за Ним много народа из Галилеи,\nи Десятиградия, и Иерусалима, и Иудеи, и из-за\nИордана."},"5":{"1":"Увидев же народ, Он поднялся на гору; и когда\nсел, подошли к Нему ученики Его.","2":"И отверзши уста Свои, Он учил их так:","3":"Блаженны нищие духом, ибо их есть Царство\nНебесное.","4":"Блаженны скорбящие, ибо они будут утешены.","5":"Блаженны кроткие, ибо они наследуют землю.","6":"Блаженны алчущие и жаждущие правды, ибо они\nбудут насыщены.","7":"Блаженны\nмилостивые,\nибо\nони\nбудут\nпомилованы.","8":"Блаженны чистые сердцем, ибо они увидят Бога.","9":"Блаженны миротворцы, ибо они будут названы\nсынами Божиими.","10":"Блаженны гонимые за правду, ибо их есть\nЦарство Небесное.","11":"Блаженны вы, когда будут поносить вас и гнать\nи злословить и лгать на вас из-за Меня.","12":"Радуйтесь и веселитесь, ибо награда ваша\nвелика на небесах: так гнали пророков, бывших прежде\nвас.","13":"Вы соль земли. Если же соль станет пресной, чем\nсделать ее соленой? Ни на что она больше не годна,\nразве только выбросить ее вон, чтобы топтали ее люди.","14":"Вы свет мира. Не может укрыться город,\nрасположенный на верху горы.","15":"И когда зажигают светильник, не ставят его под\nсосуд, но на подсвечник, и светит всем в доме.","16":"Так да воссияет свет ваш пред людьми, чтобы\nувидели они ваши добрые дела и прославили Отца\nвашего, Который на небесах.","17":"Не подумайте, что Я пришел упразднить Закон\nили Пророков. Я пришел не упразднить, но исполнить.","18":"Ибо истинно говорю вам: пока не пройдут небо и\nземля, ни одна йота или ни одна черта не пройдет в\nЗаконе, пока всё не сбудется.","19":"Поэтому, кто упразднит одну из заповедей этих\nмалейших и научит так людей, малейшим будет назван\nв Царстве Небесном; а кто исполнит и научит, тот\nвеликим будет назван в Царстве Небесном.","20":"Ибо говорю вам: если ваша праведность не будет\nбольше праведности книжников и фарисеев, не войдете\nвы в Царство Небесное.","21":"Вы слышали, что было сказано древним: «Не\nубивай; кто же убьет, будет подлежать суду».","22":"А Я говорю вам, что всякий гневающийся на\nбрата своего, будет подлежать суду; кто же скажет\nбрату своему: «рака» будет подлежать синедриону, кто\nже скажет: «глупец», будет повинен геенне огненной.","23":"Поэтому, если ты принесешь дар твой к\nжертвеннику и там вспомнишь, что брат твой имеет\nчто-нибудь против тебя, –","24":"оставь там дар твой перед жертвенником, и иди,\nпрежде помирись с братом твоим, и тогда приди и\nпринеси дар твой.","25":"Мирись с противником твоим без промедления,\nпока ты с ним на пути, чтобы не предал тебя противник\nсудье, а судья служителю, и не был ты брошен в\nтюрьму.","26":"Истинно говорю тебе: не выйдешь оттуда, доколе\nне отдашь последнего кодранта.","27":"Вы\nслышали,\nчто\nбыло\nсказано:\n«Не\nпрелюбодействуй».","28":"А Я говорю вам, что всякий, кто смотрит на\nженщину с вожделением, уже прелюбодействовал с\nнею в сердце своем.","29":"Если же глаз твой правый соблазняет тебя,\nвырви его и брось от себя; ибо лучше тебе, чтобы погиб\nодин из членов твоих, а не всё тело твое было брошено\nв геенну.","30":"И если правая рука твоя соблазняет тебя, отруби\nее и брось от себя; ибо лучше тебе, чтобы погиб один из\nчленов твоих, а не всё тело твое пошло в геенну.","31":"Было сказано: «Если кто отпустит жену свою,\nпусть даст ей разводную».","32":"А Я говорю вам, что всякий, отпускающий жену\nсвою, кроме как по причине блуда, подвергает ее\nопасности\nпрелюбодеяния,\nи\nкто\nженится\nна\nотпущенной, прелюбодействует.","33":"Еще слышали вы, что было сказано древним: «Не\nприноси ложной клятвы, но исполняй пред Господом\nклятвы твои».","34":"А Я говорю вам: не клянись вовсе: ни небом,\nпотому что оно Престол Божий;","35":"ни землею, потому что она подножие ног Его; ни\nИерусалимом, потому что он город великого Царя;","36":"ни головою твоей не клянись, потому что не\nможешь ни одного волоса сделать белым или черным.","37":"Да будет же слово ваше: «да, да», «нет, нет»; а\nчто сверх этого – от лукавого.","38":"Вы слышали, что было сказано: «Око за око, и зуб\nза зуб».","39":"А Я говорю вам: не противься злому. Но кто\nударит тебя в правую щеку, обрати к нему и другую;","40":"и желающему с тобою судиться и взять рубашку\nтвою, оставь ему и верхнюю одежду.","41":"И кто принудит тебя идти с ним тысячу шагов,\nиди с ним две.","42":"Просящему у тебя дай и от хотящего занять у\nтебя не отворачивайся.","43":"Вы слышали, что было сказано: «Возлюби\nближнего твоего и возненавидь врага твоего».","44":"А Я говорю вам: любите врагов ваших и молитесь\nза гонящих вас,","45":"чтобы стать вам сынами Отца вашего, Который\nна небесах, потому что солнце Свое Он возводит над\nзлыми и добрыми и изливает дождь на праведных и\nнеправедных.","46":"Ибо, если возлюбите любящих вас, какая вам\nнаграда? Не то же ли самое делают и мытари?","47":"И если приветствуете только братьев ваших, что\nособенного делаете? Не то же ли самое делают и\nязычники?","48":"Итак, будьте совершенны, как совершен Отец\nваш Небесный."},"6":{"1":"Наблюдайте за тем, чтобы праведность вашу не\nвыставлять перед людьми напоказ: иначе нет вам\nнаграды от Отца вашего, Который на небесах.","2":"Поэтому, когда творишь милостыню, не труби\nперед собой, как делают лицемеры в синагогах и на\nулицах, чтобы прославили их люди. Истинно говорю\nвам: они получили награду свою.","3":"Когда же ты творишь милостыню, пусть левая\nрука твоя не знает, что творит правая,","4":"чтобы милостыня твоя была втайне; и Отец твой,\nвидящий втайне, воздаст тебе.","5":"И когда молитесь, не будьте как лицемеры,\nкоторые любят молиться в синагогах и стоя на углах\nулиц, чтобы показать себя людям. Истинно говорю вам,\nони получили награду свою.","6":"Ты же, когда молишься, войди во внутренний\nпокой твой; и затворив дверь твою, помолись Отцу\nтвоему, Который втайне; и Отец твой, видящий втайне,\nвоздаст тебе.","7":"Молясь же, не разглагольствуйте как язычники;\nибо они думают, что в многословии своем будут\nуслышаны.","8":"Итак не уподобляйтесь им: ибо знает Отец ваш, в\nчем вы имеете нужду, прежде чем попросите у Него.","9":"Вы же молитесь так: Отче наш, Который на\nнебесах! Да святится имя Твое.","10":"Да придет Царство Твое. Да будет воля Твоя и на\nземле, как на небе.","11":"Хлеб наш насущный дай нам сегодня.","12":"И прости нам долги наши, как и мы простили\nдолжникам нашим.","13":"И не введи нас во искушение. Но избавь нас от\nлукавого. Ибо Твое есть Царство и сила и слава во веки.\nАминь.","14":"Ибо, если вы простите людям согрешения их,\nпростит и вам Отец ваш Небесный;","15":"если же вы не простите людям согрешений их, то\nи Отец ваш не простит согрешений ваших.","16":"Когда же поститесь, не делайтесь как лицемеры\nсумрачными; ибо они искажают лица свои, чтобы\nпоказать себя людям постящимися. Истинно говорю\nвам, они получили награду свою.","17":"Ты же, постясь, помажь твою голову и лицо твое\nумой,","18":"чтобы показать себя постящимся не людям, но\nОтцу твоему, Который втайне; и Отец твой, видящий\nвтайне, воздаст тебе.","19":"Не собирайте себе сокровищ на земле, где моль\nи тля разрушают, и где воры подкапывают и крадут;","20":"но собирайте себе сокровища на небе, где ни\nмоль, ни тля не разрушают, и где воры не подкапывают\nи не крадут;","21":"ибо, где сокровище твое, там будет и сердце\nтвое.","22":"Светильник тела есть глаз. Итак, если глаз твой\nбудет чист, то всё тело твое светло будет.","23":"Если же глаз твой плох будет, всё тело твое\nтемно будет. Итак, если свет, который в тебе, есть тьма,\nто как велика эта тьма!","24":"Никто не может служить двум господам: или\nодного возненавидит, а другого возлюбит; или к одному\nпривяжется, а другим пренебрежет. Не можете Богу\nслужить и богатству.","25":"Поэтому говорю вам: не заботьтесь для души\nвашей, что вам есть или что пить, ни для тела вашего,\nво что вам одеться. Душа не больше ли пищи, и тело –\nодежды?","26":"Посмотрите на птиц небесных: они не сеют, и не\nжнут, и не собирают в житницы; и Отец ваш Небесный\nпитает их. Разве вы не гораздо лучше их?","27":"И кто из вас, заботясь, может прибавить к сроку\nжизни своей малую меру?","28":"И об одежде что заботитесь? Поглядите на лилии\nв поле, как они растут: не трудятся и не прядут;","29":"но говорю вам, что и Соломон во всей славе\nсвоей никогда не одевался так, как любая из них.","30":"Если же траву в поле, которая сегодня есть, а\nзавтра будет брошена в печь, Бог так наряжает, не\nгораздо ли больше вас, маловеры?","31":"Итак, не заботьтесь и не говорите: «что нам\nесть?» или: «что пить?» или: «во что нам одеться?»","32":"Ибо всего этого ищут язычники: знает Отец ваш\nНебесный, что вы нуждаетесь во всём этом.","33":"Ищите же прежде Царства и правды Его, и это\nвсё приложится вам.","34":"Итак, не заботьтесь о завтрашнем дне, ибо\nзавтрашний день сам позаботится о себе: довольно для\nкаждого дня беды его."},"7":{"1":"Не судите, чтобы и вы не были судимы;","2":"ибо, каким судом судите, таким будете судимы; и\nкакою мерою мерите, такою отмерено будет вам.","3":"Что ты смотришь на соринку в глазу брата твоего,\nа бревна в твоем глазу не замечаешь?","4":"Или как скажешь брату твоему: «дай, я выну\nсоринку из глаза твоего»; а у тебя бревно в глазу?","5":"Лицемер, вынь сперва из глаза твоего бревно, и\nтогда увидишь, как вынуть соринку из глаза брата\nтвоего.","6":"Не давайте святыни псам и не бросайте жемчуга\nвашего перед свиньями, чтобы они не затоптали его\nногами и, обернувшись, не растерзали вас.","7":"Просите, и дано будет вам; ищите, и найдете;\nстучитесь, и отворят вам.","8":"Ибо всякий просящий получает, и ищущий\nнаходит, и стучащемуся отворят.","9":"Или есть между вами такой человек, у которого\nсын его попросит хлеба, а он подаст ему камень?","10":"Или рыбы попросит, а он подаст ему змею?","11":"Итак, если вы, будучи злы, умеете давать дары\nблагие детям вашим, тем более Отец ваш, Который на\nнебесах, даст благо просящим у Него.","12":"Итак во всем, как хотите, чтобы люди поступали\nс вами, так с ними поступайте и вы, ибо это – Закон и\nПророки.","13":"Входите узкими вратами, ибо широки врата и\nпросторен путь, ведущий в гибель, и многие идут им.","14":"Ибо узки врата и тесен путь, ведущий в жизнь, и\nнемногие находят его.","15":"Остерегайтесь лжепророков, которые приходят к\nвам в одежде овечьей, внутри же – волки хищные.","16":"По плодам их познаете их. Разве собирают с\nтерния виноград или с репейника смоквы?","17":"Так всякое хорошее дерево производит добрые\nплоды, плохое же дерево производит дурные плоды:","18":"не может хорошее дерево приносить дурные\nплоды, ни плохое дерево приносить добрые плоды.","19":"Всякое дерево, не приносящее доброго плода,\nсрубается и бросается в огонь.","20":"Итак, по плодам их познаете их.","21":"Не всякий говорящий Мне: «Господи! Господи!»\nвойдет в Царство Небесное, но исполняющий волю Отца\nМоего, Который на небесах.","22":"Многие скажут Мне в тот день: «Господи!\nГосподи! Не от Твоего ли имени мы пророчествовали? И\nне Твоим ли именем бесов изгоняли? И не Твоим ли\nименем много чудес совершили?»","23":"И тогда объявлю им: «Я никогда не знал вас:\nудалитесь от Меня, делающие беззаконие».","24":"Поэтому всякий, кто слушает эти Мои слова и\nисполняет их, подобен будет мужу разумному, который\nпостроил свой дом на скале.","25":"И пролился дождь, и разлились реки, и подули\nветры, и обрушились на дом тот; и он не рухнул, ибо\nоснование его было положено на скале.","26":"И всякий, слушающий эти Мои слова и не\nисполняющий их, подобен будет мужу безрассудному,\nкоторый построил свой дом на песке;","27":"и пролился дождь, и разлились реки, и подули\nветры, и налегли на дом тот; и он рухнул, и разрушение\nего было великое.","28":"И было: когда окончил Иисус слова эти,\nизумлялся народ учению Его.","29":"Ибо учил Он их как власть имеющий, а не как\nкнижники их."},"8":{"1":"Когда же сошел Он с горы, за Ним последовало\nмного народа.","2":"И вот, прокаженный подошел и кланялся Ему,\nговоря:\nГосподи,\nесли\nТы\nхочешь,\nможешь\nменя\nочистить,","3":"И протянув руку, Он коснулся его и сказал: хочу,\nочистись. И тотчас очистился он от проказы.","4":"И говорит ему Иисус: смотри, никому не говори; но\nиди, покажись священнику и принеси дар, какой\nповелел Моисей, во свидетельство им.","5":"Когда же вошел Он в Капернаум, подошел к Нему\nсотник и просил Его:","6":"Господи, отрок мой лежит дома расслабленный и\nжестоко страдает.","7":"Иисус говорит ему: Я приду и исцелю его.","8":"Но сотник ответил: Господи, я недостоин, чтобы\nТы ко мне вошел под кров, но только скажи, и будет\nисцелен отрок мой;","9":"ведь я человек подвластный, имеющий в своем\nподчинении воинов, и говорю одному: «пойди», и идет;\nи другому: «приходи», и приходит; и этому рабу моему:\n«сделай это», и делает.","10":"Услышав\nже\nИисус\nудивился\nи\nсказал\nсопровождающим: истинно говорю вам: Я и в Израиле\nне нашел такой веры.","11":"Говорю же вам, что многие придут с востока и\nзапада и возлягут с Авраамом, Исааком и Иаковом в\nЦарстве Небесном;","12":"сыны же Царства извержены будут во тьму\nвнешнюю: там будет плач и скрежет зубов.","13":"И сказал Иисус сотнику: иди; как ты поверил, да\nбудет тебе. И исцелен был отрок в час тот.","14":"И придя в дом Петра, Иисус увидел, что теща его\nлежит в горячке.","15":"И Он коснулся руки ее, и оставила ее горячка; и\nона встала и служила Ему.","16":"С наступлением же вечера привели к Нему\nмногих бесноватых, и Он изгнал духов словом и всех\nнедужных исцелил.","17":"Дабы\nисполнилось\nсказанное\nчрез\nИсаию\nпророка: Он взял наши немощи и понес болезни.","18":"Увидев же вокруг себя народ, Иисус повелел\nпереправиться на другую сторону.","19":"И подошел один книжник и сказал Ему: Учитель,\nя буду следовать за Тобой, куда бы Ты ни шел.","20":"И говорит ему Иисус: у лисиц есть норы, и у птиц\nнебесных – гнезда. Сыну же Человеческому некуда\nголову приклонить.","21":"Другой же из учеников сказал Ему: Господи,\nпозволь мне прежде пойти и похоронить отца моего.","22":"Но Иисус говорит ему: следуй за Мною и\nпредоставь мертвым хоронить своих мертвых.","23":"И когда вошел Он в лодку, последовали за Ним\nученики Его.","24":"И вот, сделалось великое волнение в море, так\nчто лодку заливало волнами; Он же спал.","25":"И подойдя, разбудили Его, говоря: Господи!\nСпаси: погибаем.","26":"И говорит им: как вы боязливы, маловерные!\nТогда, встав, Он возбранил ветрам и морю, и настала\nвеликая тишина.","27":"Люди же удивились и говорили: Кто это, что и\nветры и море повинуются Ему?","28":"И когда Он прибыл на другой берег в страну\nГадаринскую, Его встретили, выходя из могильных\nпещер, два бесноватых, столь свирепых, что тем путем\nникто не мог пройти.","29":"И вот они закричали: что Тебе до нас, Сын\nБожий? Пришел Ты сюда прежде времени мучить нас.","30":"Вдали же от них паслось большое стадо свиней.","31":"И бесы просили Его: если Ты изгоняешь нас,\nпошли нас в стадо свиней.","32":"И Он сказал им: идите. Они, выйдя, пошли в\nсвиней. И вот ринулось всё стадо с крутизны в море, и\nсвиньи погибли в воде.","33":"А пастухи побежали и, придя в город, объявили о\nвсём, и о бесноватых.","34":"И вот весь город вышел навстречу Иисусу. И\nкогда они увидели Его, попросили удалиться из области\nих."},"9":{"1":"И войдя в лодку, Он переправился и прибыл в\nгород Свой.","2":"И вот несут к Нему расслабленного, лежащего на\nпостели. Иисус, увидев веру их, сказал расслабленному:\nдерзай, чадо! Прощаются грехи твои.","3":"И вот, некоторые из книжников сказали самим\nсебе: Он богохульствует.","4":"Иисус, зная мысли их, сказал: почему вы мыслите\nдурное в сердцах ваших?","5":"Ибо что легче? Сказать ли: «прощаются грехи\nтвои», или сказать: «встань и ходи»?","6":"Но чтобы вы знали, что власть имеет Сын\nЧеловеческий на земле прощать грехи, – тогда говорит\nрасслабленному : встань, возьми постель твою и иди в\nдом твой.","7":"И встав, он пошел в дом свой.","8":"Народ же, увидев, устрашился и прославил Бога,\nдавшего такую власть людям.","9":"И проходя оттуда, Иисус увидел человека,\nсидящего у сбора пошлин, по имени Матфея, и говорит\nему: следуй за Мною. И он встал и последовал за Ним.","10":"Было: когда Он возлежал в доме, многие мытари\nи грешники пришли и возлегли с Ним и с учениками Его.","11":"И увидев, фарисеи говорили ученикам Его:\nпочему Учитель ваш ест с мытарями и грешниками?","12":"Услышав же это, Он сказал им: не здоровым\nнужен врач, а болящим.","13":"Пойдите, научитесь, что значит: «Милости хочу, а\nне жертвы». Я пришел призвать не праведных, но\nгрешных.","14":"Тогда приходят к Нему ученики Иоанновы и\nговорят: почему мы и фарисеи постимся, а ученики Твои\nне постятся?","15":"И сказал им Иисус: могут ли сыны чертога\nбрачного скорбеть, пока с ними Жених? Но придут дни,\nкогда взят будет от них Жених, и тогда будут\nпоститься.","16":"И никто не ставит заплату из новой ткани на\nветхой одежде. Пришитый кусок ее разорвет, и дыра\nбудет хуже.","17":"И не наливают вино молодое в мехи ветхие,\nиначе прорываются мехи, и вино вытекает, и мехи\nпропадают; но наливают вино молодое в меха новые, и\nсохраняется и то и другое.","18":"Когда Он говорил им это, – вот, один начальник\nподошел и кланялся Ему, говоря: дочь моя только что\nскончалась; но приди, возложи руку Твою на нее, и она\nоживет.","19":"И встав, Иисус последовал за ним, и ученики Его.","20":"И\nвот\nженщина,\nбольная\nкровотечением\nдвенадцать лет, подойдя сзади, прикоснулась к краю\nодежды Его.","21":"Говорила\nона\nсебе\nсамой:\nесли\nтолько\nприкоснусь к одежде Его, буду спасена.","22":"Иисус же обернулся и, увидев ее, сказал: дерзай,\nдочь Моя, вера твоя спасла тебя. И спасена была\nженщина в час тот.","23":"И говорил Иисус, придя в дом начальника и\nувидев играющих на свирели и толпу шумящую:","24":"выйдите; не умерла девица, но спит. И смеялись\nнад Ним.","25":"Когда же удалена была толпа, Он вошел и взял\nее за руку, и встала девица.","26":"И прошел слух об этом по всей земле той.","27":"И когда Иисус проходил оттуда, последовало за\nНим двое слепых, крича Ему: помилуй нас. Сын Давидов!","28":"А когда Он вошел в дом, слепые к Нему подошли.\nИ говорит им Иисус: верите ли, что Я могу это сделать?\nОни говорят Ему: да, Господи!","29":"Тогда Он коснулся их глаз и сказал: по вере\nвашей да будет вам.","30":"И открылись глаза их. И строго наказал им Иисус:\nсмотрите, пусть никто не знает.","31":"Они же, выйдя, разгласили о Нем по всей земле\nтой.","32":"Когда же они выходили, вот, привели к Нему\nнемого бесноватого.","33":"И когда бес был изгнан, заговорил немой. И\nудивлялся народ, говоря: никогда не было такого\nявления в Израиле.","34":"А фарисеи говорили: Он изгоняет бесов силою\nкнязя бесовского.","35":"И обходил Иисус все города и селения, уча в\nсинагогах их и проповедуя Евангелие Царства и\nисцеляя всякую болезнь и всякую немощь.","36":"Увидев же толпы народа, Он сжалился над ними,\nпотому что они были изнурены и полегли, как овцы без\nпастыря.","37":"Тогда говорит ученикам Своим: жатвы много, а\nработников мало:","38":"поэтому молите Господина жатвы, чтобы выслал\nработников на жатву Свою."},"10":{"1":"И призвав двенадцать учеников Своих, Он дал им\nвласть над нечистыми духами, чтобы изгонять их и\nисцелять всякую болезнь и всякую немощь.","2":"Имена двенадцати апостолов следующие: первый\nСимон, называемый Петром, и Андрей, брат его, Иаков\nЗеведеев и Иоанн, брат его,","3":"Филипп и Варфоломей, Фома и Матфей мытарь,\nИаков Алфеев и Фаддей,","4":"Симон Кананит и Иуда Искариот, который и был\nпредателем Его.","5":"Этих двенадцать послал Иисус и дал им такие\nповеления: на путь к язычникам не идите и в город\nсамарянский не входите;","6":"идите лучше к овцам погибшим дома Израилева.","7":"И когда пойдете, проповедуйте и говорите:\n«близко Царство Небесное».","8":"Болящих\nисцеляйте,\nмертвых\nвоскрешайте,\nпрокаженных\nочищайте,\nбесов\nизгоняйте;\nдаром\nполучили, даром давайте.","9":"Не берите себе ни золота, ни серебра, ни меди в\nпояса свои,","10":"ни сумы на дорогу, ни двух рубашек, ни обуви, ни\nпосоха. Ибо работник достоин пропитания своего.","11":"И в какой бы город или селение вы ни вошли,\nузнайте, кто в нем достоин, и там пребудьте, пока не\nвыйдете.","12":"Входя же в дом, приветствуйте его, говоря: «мир\nдому сему»;","13":"и если дом будет достоин, да придет мир ваш на\nнего; если же не будет достоин, мир ваш к вам да\nвозвратится.","14":"А кто не примет вас и не послушает слов ваших,\nстряхните пыль от ног ваших, выходя вон из дома или\nиз города того.","15":"Истинно\nговорю\nвам:\nлегче\nбудет\nземле\nСодомской и Гоморрской в день суда, чем городу тому.","16":"Вот, Я посылаю вас, как овец посреди волков:\nитак, будьте разумны как змеи, и бесхитростны как\nголуби.","17":"Берегитесь же людей: ибо они предадут вас в\nсудилища\nи\nв\nсинагогах\nсвоих\nподвергнут\nвас\nбичеванию.","18":"И к правителям и царям поведут вас за Меня во\nсвидетельство им и язычникам.","19":"И когда предадут вас, не заботьтесь, как или что\nвам сказать ; ибо дано будет вам в тот час, что сказать;","20":"ибо не вы будете говорить, но Дух Отца вашего\nбудет говорить в вас.","21":"Предаст же брат брата на смерть, и отец дитя\nсвое; и восстанут дети на родителей и умертвят их;","22":"и будете ненавидимы всеми за имя Мое.\nПретерпевший же до конца, тот и будет спасен.","23":"Когда же будут гнать вас в одном городе, бегите\nв другой. Ибо истинно говорю вам: не успеете вы обойти\nгородов Израилевых, как придет Сын Человеческий.","24":"Ученик не выше учителя, и раб не выше\nгосподина своего:","25":"достаточно для ученика, чтобы он стал, как\nучитель его, и раб – как господин его. Если хозяина\nдома прозвали Веельзевулом, тем более – домашних\nего.","26":"Поэтому не бойтесь их: ибо нет ничего скрытого,\nчто не открылось бы, и тайного, чего не узнали бы.","27":"Что говорю вам в темноте, скажите при свете; и\nчто на ухо слышите, проповедуйте на кровлях.","28":"И не бойтесь убивающих тело, души же не\nмогущих убить; а бойтесь лучше могущего и душу и\nтело погубить в геенне.","29":"Не два ли воробья продаются за ассарий? И ни\nодин из них не упадет на землю без воли Отца вашего,","30":"У вас же и волосы на голове все сосчитаны,","31":"Не бойтесь же: вы лучше многих воробьев.","32":"Итак, всякого, кто исповедает Меня перед\nлюдьми, исповедаю и Я его перед Отцом Моим, Который\nна небесах;","33":"и кто отречется от Меня перед людьми, отрекусь\nи Я от него перед Отцом Моим, Который на небесах.","34":"Не подумайте, что Я пришел принести мир на\nземлю; Я пришел принести не мир, но меч.","35":"Ибо Я пришел разделить человека с отцом его, и\nдочь с матерью ее, и невестку со свекровью ее.","36":"И враги человека – домашние его.","37":"Любящий отца или мать более Меня недостоин\nМеня; и любящий сына или дочь более Меня недостоин\nМеня;","38":"и кто не берет креста своего и не следует за\nМною, недостоин Меня.","39":"Нашедший душу свою потеряет ее, и потерявший\nдушу свою за Меня найдет ее.","40":"Принимающий вас Меня принимает, и Меня\nпринимающий принимает Пославшего Меня.","41":"Принимающий пророка во имя пророка получит\nнаграду пророка, и принимающий праведного во имя\nправедного получит награду праведного.","42":"И кто напоит одного из малых сих чашей\nхолодной воды только во имя ученика, истинно говорю\nвам, не потеряет награды своей."},"11":{"1":"И\nбыло:\nкогда\nокончил\nИисус\nнаставления\nдвенадцати ученикам Своим, перешел Он оттуда учить\nи проповедовать в городах их.","2":"Иоанн же, услышав в тюрьме о делах Христовых,\nпослал через учеников своих","3":"сказать Ему: Ты ли Грядущий, или ожидать нам\nиного?","4":"И ответил им Иисус: пойдите, возвестите Иоанну,\nчто слышите и видите:","5":"слепые прозревают, и хромые ходят; прокаженные\nочищаются, и глухие слышат; мертвые восстают, и\nнищим благовествуется;","6":"и блажен тот, кто не соблазнится из-за Меня.","7":"Когда же они уходили, начал Иисус говорить\nнароду об Иоанне: что смотреть ходили вы в пустыню?\nНе тростник же, ветром колеблемый?","8":"Но зачем же вы ходили? Чтобы увидеть человека,\nоблеченного в мягкие одежды? Но носящие мягкие\nодежды – в домах царей.","9":"Так зачем же вы ходили? Увидеть пророка? Да,\nговорю вам, и больше чем пророка,","10":"Это тот, о ком написано: «Вот Я посылаю ангела\nМоего пред лицом Твоим, который приготовит путь Твой\nпред Тобою».","11":"Истинно говорю вам: не восставало среди\nрожденных женами большего чем Иоанн Креститель, но\nменьший в Царстве Небесном больше его.","12":"От дней же Иоанна Крестителя доныне Царство\nНебесное силою берется, и употребляющие усилие\nовладевают им;","13":"ибо все Пророки и Закон пророчествовали до\nИоанна.","14":"И если хотите принять, он есть Илия, имеющий\nпридти.","15":"Кто имеет уши слышать, да слышит!","16":"Кому же уподоблю род этот? Он подобен детям,\nсидящим на площадях, которые, обращаясь к другим,","17":"говорят: «Мы играли вам на свирели, и вы не\nплясали; мы пели вам печальные песни, и вы не били\nсебя в грудь».","18":"Ибо пришел Иоанн, и не ест и не пьет; и говорят:\n«в нем бес».","19":"Пришел Сын Человеческий, ест и пьет; и говорят:\n«вот человек, любящий есть и пить вино, друг мытарей\nи грешников». И оправданием премудрости были дела\nее.","20":"Тогда начал Он укорять города, в которых\nсовершилась большая часть чудес Его, за то, что они не\nпокаялись.","21":"Горе тебе, Хоразин! Горе тебе, Вифсаида! Ибо,\nесли\nбы\nв\nТире\nи\nСидоне\nсовершились\nчудеса,\nсовершившиеся в вас, то давно бы они в рубище и пепле\nпокаялись;","22":"но говорю вам: Тиру и Сидону легче будет в день\nсуда, чем вам.","23":"И ты, Капернаум, до неба ли ты будешь\nвознесён? До ада ты будешь низвергнут; потому что\nесли\nбы\nв\nСодоме\nбыли\nсовершены\nчудеса,\nсовершившиеся в тебе, он остался бы до сего дня.","24":"Но говорю вам, что земле Содомской легче будет\nв день суда, чем тебе.","25":"В то время, продолжая речь, Иисус сказал:\nславлю Тебя, Отче, Господи неба и земли, что Ты скрыл\nэто от мудрых и разумных и открыл это младенцам;","26":"да, Отче, ибо так было благоугодно Тебе.","27":"Всё Мне предано Отцом Моим, и никто не знает\nСына, кроме Отца; и Отца не знает никто, кроме Сына, и\nкому хочет Сын открыть.","28":"Придите\nко\nМне\nвсе\nтруждающиеся\nи\nобремененные, и Я упокою вас;","29":"возьмите иго Мое на себя и научитесь от Меня,\nибо Я кроток и смирен сердцем, и найдете покой душам\nвашим;","30":"ибо иго Мое благо, и бремя Мое легко."},"12":{"1":"В то время шел Иисус в субботу засеянными\nполями. Ученики Его проголодались и начали срывать\nколосья и есть.","2":"Фарисеи же увидели и сказали Ему: вот, ученики\nТвои делают, чего нельзя делать в субботу,","3":"А Он сказал им: не читали вы, что сделал Давид,\nкогда проголодался он и сопровождавшие его?","4":"Как он вошел в дом Божий, и они съели хлебы\nпредложения, которых нельзя было ни ему есть, ни\nсопровождавшим его, а одним только священникам?","5":"Или не читали вы в Законе, что в субботу\nсвященники нарушают субботу в храме и вины не\nнесут?","6":"Но говорю вам: то, что здесь, – больше храма.","7":"Если бы вы понимали, что значит: «Милости хочу,\nа не жертвы», то не осудили бы невиновных.","8":"Ибо Сын Человеческий есть господин субботы.","9":"И перейдя оттуда в другое место, Он пришел в\nсинагогу их.","10":"И вот человек с сухою рукой. И спросили Его,\nчтобы\nобвинить\nЕго:\nдозволяется\nли\nисцелять\nв\nсубботу?","11":"Он же сказал им: если у кого из вас его\nединственная овца упадет в субботу в яму, неужели он\nне возьмет ее и не поднимет?","12":"Насколько же лучше человек овцы! Итак,\nдозволяется делать добро в субботу.","13":"Тогда говорит человеку: протяни твою руку; и он\nпротянул; и стала она вновь здоровой, как другая.","14":"Фарисеи же, выйдя, приняли против Него\nрешение, чтобы погубить Его. Но Иисус, узнав, удалился\nоттуда.","15":"И последовали за Ним многие, и Он исцелил их\nвсех.","16":"И строго приказал им не разглашать о Нем,","17":"чтобы исполнилось сказанное чрез пророка\nИсаию, который говорит:","18":"Вот\nОтрок\nМой,\nКоторого\nЯ\nизбрал,\nВозлюбленный Мой, к Которому благоволит душа Моя.\nПоложу Дух Мой на Него, и возвестит язычникам\nправосудие.","19":"Он не вступит в спор и не подымет крика, и не\nуслышит никто на улицах голоса Его.","20":"Он тростника надломленного не переломит и\nфитиля тлеющего не погасит, доколе не даст торжества\nправосудию;","21":"и на имя Его язычники будут уповать.","22":"Тогда приведен был к Нему бесноватый слепой и\nнемой; и Он исцелил его, так что слепой и немой стал\nговорить и видеть.","23":"И изумлялся весь народ и говорил: уж не Сын ли\nОн Давидов?","24":"Фарисеи же, услышав это, сказали: Он изгоняет\nбесов не иначе, как Веельзевулом, князем бесовским.","25":"Зная помышления их, Он сказал им: всякое\nцарство,\nразделенное\nвнутреннею\nвраждой,\nобращается в пустыню: и ни один город или дом,\nразделенный внутреннею враждой, не устоит.","26":"И если сатана сатану изгоняет, то он в самом\nсебе разделился: как же устоит царство его?","27":"И если Я Веельзевулом изгоняю бесов, сыновья\nваши кем изгоняют? Поэтому они вам будут судьями.","28":"Если же Я Духом Божиим изгоняю бесов, значит,\nдостигло до вас Царство Божие.","29":"Или как может кто войти в дом сильного и\nпохитить его вещи, если прежде не свяжет сильного? И\nтогда он расхитит дом его.","30":"Кто не со Мною, тот против Меня; и кто не\nсобирает со Мною, тот расточает.","31":"Поэтому говорю вам: всякий грех и хула будут\nпрощены людям; но хула на Духа не будет прощена\nлюдям.","32":"И кто скажет слово против Сына Человеческого,\nбудет прощено ему; кто же скажет против Духа\nСвятого, не будет прощено ему ни в этом веке, ни в\nбудущем.","33":"Или назовите дерево добрым и плод его добрым,\nили назовите дерево плохим и плод его плохим; ведь по\nплоду познается дерево.","34":"Отродье змеиное, как можете вы говорить\nдоброе, будучи злы? Ибо от избытка сердца говорят\nуста.","35":"Добрый человек из доброго сокровища выносит\nдоброе; и злой человек из злого сокровища выносит\nзлое.","36":"Говорю же вам, что за всякое слово праздное,\nкакое скажут люди, дадут они отчет в день суда;","37":"ибо по словам твоим будешь ты оправдан, и по\nсловам твоим будешь ты осужден.","38":"Тогда ответили Ему некоторые из книжников и\nфарисеев: Учитель, мы хотим видеть от Тебя знамение.","39":"И Он ответил им: род лукавый и прелюбодейный\nзнамения ищет; и не будет дано ему знамения, кроме\nзнамения Ионы пророка;","40":"ибо, как был Иона во чреве кита три дня и три\nночи, так будет Сын Человеческий в сердце земли три\nдня и три ночи.","41":"Люди Ниневийские восстанут во время суда\nвместе с родом этим и осудят его, потому что они\nпокаялись от проповеди Ионы; и вот, то, что здесь, –\nбольше Ионы.","42":"Царица Юга будет воздвигнута во время суда\nвместе с родом этим и осудит его, потому что она\nпришла\nот\nпределов\nземли\nпослушать\nмудрость\nСоломонову; и вот, то, что здесь, – больше Соломона.","43":"Когда же нечистый дух выйдет из человека, то\nбродит по безводным местам, ища покоя, и не находит.","44":"Тогда говорит он: «в дом мой возвращусь, откуда\nя\nвышел».\nИ\nпридя,\nнаходит\nего\nнезанятым,\nвыметенным и убранным.","45":"Тогда он идет и берет с собой семь других духов,\nзлейших себя, и, войдя, они поселяются там; и\nстановится для человека того последнее хуже первого.\nТак будет и с этим лукавым родом.","46":"Пока еще Он говорил народу, вот, Матерь и\nбратья\nЕго\nпришли\nи\nстояли\nснаружи,\nстараясь\nпоговорить с Ним.","47":"И сказал Ему кто-то: вот, Матерь Твоя и братья\nТвои пришли и стоят снаружи, стараясь с Тобою\nпоговорить.","48":"Он же ответил говорившему Ему: кто матерь\nМоя, и кто братья Мои?","49":"И протянув руку Свою к ученикам Своим, сказал:\nвот матерь Моя и братья Мои;","50":"ибо кто исполнит волю Отца Моего, Который на\nнебесах, тот Мой брат и сестра и матерь."},"13":{"1":"В тот день Иисус, выйдя из дома, сидел у моря.","2":"И собралось к Нему много народа, так что Он\nвошел в лодку и сидел, а весь народ стоял на берегу,","3":"И сказал им многое в притчах. Он говорил: вот,\nвышел сеятель сеять.","4":"И когда сеял, некоторые семена упали при дороге,\nи прилетели птицы и поклевали их.","5":"Другие же упали на камень, где у них немного\nбыло земли, и тотчас взошли, ибо земля у них не была\nглубока.","6":"Когда же солнце взошло, они были опалены и, не\nимея корня, засохли.","7":"Другие же упали в терние, и поднялось терние и\nзаглушило их.","8":"Другие же упали на землю добрую и давали плод:\nкакое – сто, какое – шестьдесят, какое – тридцать.","9":"Имеющий уши да слышит.","10":"И подойдя, ученики сказали Ему: почему Ты\nговоришь им притчами?","11":"И Он ответил им: потому что вам дано познать\nтайны Царства Небесного, тем же не дано;","12":"ибо, кто имеет, тому будет дано, и будет у него\nизобилие; а кто не имеет, у того будет взято и то, что\nимеет.","13":"Потому говорю им притчами, что они видя не\nвидят, и слыша не слышат, и не разумеют;","14":"и исполняется на них пророчество Исаии,\nкоторое говорит: «Слухом будете слышать, и не\nуразумеете; и глазами глядеть будете, и не увидите;","15":"ибо ожирело сердце народа этого, и ушами они\nедва слышат, и глаза свои они закрыли, чтобы не\nувидеть глазами и ушами не услышать и сердцем не\nуразуметь и не обратиться. И Я исцелю их».","16":"Ваши же блаженны очи, что видят, и уши ваши,\nчто слышат;","17":"ибо истинно говорю вам: многие пророки и\nправедные желали видеть то, что вы видите, и не\nувидели, и слышать то, что вы слышите, и не услышали.","18":"Вы же вслушайтесь в притчу о сеятеле.","19":"Ко всякому, кто слышит слово о Царстве и не\nразумеет, приходит лукавый и похищает посеянное в\nсердце его: это посеянный при дороге.","20":"А посеянный на камне – это слышащий слово и\nтотчас с радостью принимающий его;","21":"но не имеет он корня в себе и держится короткое\nвремя; с наступлением же скорби или гонения за слово\nтотчас соблазняется.","22":"А посеянный в тернии – это слышащий слово, но\nзабота века и обольщение богатства заглушают слово, и\nоно делается бесплодным.","23":"А посеянный на доброй земле – это слышащий\nслово и разумеющий; он-то и дает плод и приносит: кто\n– сто, кто – шестьдесят, кто – тридцать.","24":"Другую притчу предложил Он им: подобно\nЦарство Небесное человеку, посеявшему доброе семя в\nполе своем;","25":"когда же люди спали, пришел его враг и посеял\nмежду пшеницею плевелы и ушел;","26":"а когда взошла зелень и дала плод, тогда\nявились и плевелы.","27":"И\nпридя,\nрабы\nдомохозяина\nсказали\nему:\n«господин, не доброе ли семя посеял ты в твоем поле?\nОткуда же в нем плевелы?»","28":"Он сказал им: «враг человек это сделал.» Рабы\nже ему говорят: «так хочешь, мы пойдем, выберем их?»","29":"Он говорит: «нет, чтобы, выбирая плевелы, вы не\nвырвали с корнем вместе с ними пшеницу,","30":"Дайте им вместе расти до жатвы; и во время\nжатвы я скажу жнецам: выберите прежде плевелы и\nсвяжите их в связки, чтобы сжечь их; а пшеницу\nсоберите в житницу мою».","31":"Другую притчу предложил Он им: подобно\nЦарство Небесное зерну горчичному, которое взял\nчеловек и посеял в поле своем.","32":"Хотя оно и меньше всех семян, но когда\nвырастет, оно больше овощей и становится деревом,\nтак что птицы небесные прилетают и вьют гнёзда в\nветвях его.","33":"Другую притчу сказал Он им: подобно Царство\nНебесное закваске, которую взяла женщина и положила\nв три меры муки, доколе не вскисло всё.","34":"Это всё сказал Иисус народу в притчах, и без\nпритчи не говорил им ничего,","35":"дабы исполнилось сказанное чрез пророка:\nОткрою в притчах уста Мои; провозглашу сокровенное\nот основания мира.","36":"Тогда, оставив народ. Он вошел в дом. И\nподошли к Нему ученики Его и сказали: разъясни нам\nпритчу о плевелах в поле.","37":"И Он ответил: сеющий доброе семя – Сын\nЧеловеческий ;","38":"поле – мир; доброе семя – это сыны Царства;\nплевелы – сыны лукавого.","39":"Враг, посеявший их, – диавол; жатва – конец\nвека: жнецы – ангелы.","40":"Поэтому, как выбираются плевелы и огнем\nсжигаются, так будет в конце века:","41":"пошлет Сын Человеческий ангелов Своих, и\nвыберут из Царства Его все соблазны и делающих\nбеззаконие,","42":"и бросят их в печь огненную; там будет плач и\nскрежет зубов.","43":"Тогда праведные будут сиять как солнце в\nЦарстве Отца их. Имеющий уши да слышит.","44":"Подобно Царство Небесное зарытому в поле\nсокровищу, которое человек, найдя, скрыл, и от радости\nидет и продает всё, что имеет, и покупает поле то.","45":"Еще подобно Царство Небесное купцу, ищущему\nхороших жемчужин.","46":"Найдя одну многоценную жемчужину, он пошел\nи продал всё, что имел, и купил ее.","47":"Еще подобно Царство Небесное большой сети,\nзакинутой в море и собравшей рыб всякого рода.","48":"Когда она наполнилась, ее вытащили на берег и,\nсев, собрали хорошее в сосуды, а плохое выбросили вон.","49":"Так будет в конце века: выйдут ангелы и отделят\nзлых от праведных","50":"и бросят их в печь огненную: там будет плач и\nскрежет зубов.","51":"Уразумели ли вы всё это? Они говорят Ему: да!","52":"И Он сказал им: поэтому всякий книжник,\nнаученный\nЦарству\nНебесному,\nподобен\nчеловеку\nхозяину дома, который выносит из сокровища своего\nновое и старое.","53":"И было: когда окончил Иисус притчи эти, Он\nушел оттуда.","54":"И придя в отечество Свое, учил их в синагоге их,\nтак что изумлялись они и говорили: откуда у Него\nпремудрость эта и силы?","55":"Не Он ли сын плотника? Не Мать ли Его\nназывается Мариам, и братья Его Иаков, Иосиф, Симон и\nИуда?","56":"И сестры Его не все ли с нами? У Него же откуда\nвсё это?","57":"И соблазнялись из-за Него. Иисус же сказал им:\nпророк не бывает без чести, разве только в отечестве и\nв доме своем.","58":"И не сотворил там многих чудес по неверию их."},"14":{"1":"В то время дошел до Ирода тетрарха слух об\nИисусе.","2":"И сказал он слугам своим: это Иоанн Креститель;\nон восстал из мертвых, и поэтому силы действуют в\nнем.","3":"Ибо Ирод, взяв Иоанна, связал и заключил его в\nтюрьму за Иродиаду, жену Филиппа, брата своего,","4":"потому что Иоанн говорил ему: нельзя тебе иметь\nее.","5":"И хотел Ирод убить его, но страх перед народом\nего остановил, оттого что Иоанна считали пророком.","6":"Но в день рождения Ирода дочь Иродиады\nплясала перед собранием и угодила Ироду;","7":"поэтому он с клятвой обещал ей дать, чего бы она\nни попросила.","8":"Она же, по внушению матери своей, говорит: дай\nмне здесь же на блюде голову Иоанна Крестителя.","9":"И как ни огорчен был царь, но ради клятвы и\nвозлежащих с ним, повелел дать.","10":"И послал обезглавить Иоанна в тюрьме,","11":"и голову его принесли на блюде и дали девице, и\nона отнесла ее матери своей.","12":"И пришли ученики его и взяли тело и погребли\nего; и пошли, возвестили Иисусу.","13":"Услышав же Иисус удалился оттуда на лодке в\nпустынное место отдельно от других, и народ услышал\nо том и последовал за Ним пешком из городов.","14":"И выйдя, Он увидел много народа и сжалился\nнад ними и исцелил их больных.","15":"С наступлением же вечера подошли к Нему\nученики и сказали: пустынно это место, и час уже\nпоздний; отпусти народ, чтобы они пошли в селения и\nкупили себе пищи.","16":"Иисус же сказал им: не нужно им идти; дайте им\nвы поесть.","17":"Они говорят Ему: нет у нас здесь ничего: только\nпять хлебов и две рыбы.","18":"Он сказал: несите Мне их сюда.","19":"И велев народу возлечь на траве, взял эти пять\nхлебов\nи\nэти\nдве\nрыбы,\nподнял\nглаза\nк\nнебу,\nблагословил и, преломив, дал ученикам хлебы, ученики\nже – народу.","20":"И ели все и насытились, и собрали остававшихся\nкусков двенадцать коробов полных.","21":"Евших же было мужчин около пяти тысяч, кроме\nженщин и детей.","22":"И тотчас заставил Он учеников войти в лодку и\nпереправиться раньше Его на другую сторону, пока Он\nне отпустит народ.","23":"И отпустив народ, Он поднялся на гору отдельно\nот других помолиться, и с наступлением вечера был там\nодин.","24":"А лодка была уже на середине моря, и било ее\nволнами: ибо ветер был противный.","25":"В четвертую же стражу ночи Он пришел к ним,\nступая по морю.","26":"Ученики же, увидев, что Он идет по морю, были\nсмущены\nи\nговорили:\nэто\nпризрак;\nи\nот\nстраха\nзакричали.","27":"И тотчас заговорил с ними Иисус и сказал:\nмужайтесь; это Я, не бойтесь.","28":"А Петр Ему ответил: Господи, если это Ты, повели\nмне пойти к Тебе по воде.","29":"Он сказал: иди. И выйдя из лодки, Петр пошел по\nводе и подошел к Иисусу:","30":"видя же ветер, испугался и, начав тонуть,\nзакричал: Господи, спаси меня.","31":"И тотчас Иисус, протянув руку, поддержал его и\nговорит ему: маловерный, почему ты усомнился?","32":"И когда вошли они в лодку, прекратился ветер.","33":"Бывшие же в лодке поклонились Ему и сказали:\nвоистину Ты Сын Божий.","34":"И переправившись, они достигли земли в\nГеннисарете.","35":"И узнав Его, жители того места послали во всю\nокругу, и привели к Нему всех больных,","36":"и просили Его, чтобы только прикоснуться к краю\nодежды Его; и те, которые прикоснулись, были спасены."},"15":{"1":"Тогда приходят к Иисусу из Иерусалима фарисеи и\nкнижники и говорят:","2":"почему\nученики\nТвои\nпреступают\nпредание\nстарцев? Ибо не моют они рук, когда едят хлеб.","3":"А Он им ответил: почему и вы преступаете\nзаповедь Божию ради предания вашего?","4":"Сказал же Бог: «Почитай отца и мать»; и:\n«Злословящий отца или мать смертию да умрет».","5":"А вы говорите: кто скажет отцу или матери: «дар\nто, чем бы ты от меня воспользовался»,","6":"тот да не почтит отца своего или мать свою; и\nотменили вы слово Божие ради предания вашего.","7":"Лицемеры! Хорошо пророчествовал о вас Исаия:","8":"«Народ этот устами Меня чтит, сердце же их\nдалеко отстоит от Меня;","9":"но тщетно воздают Мне почитание, уча учениям,\nпредписаниям человеческим».","10":"И призвав народ, сказал им: слушайте и\nразумейте:","11":"не то, что входит в уста, оскверняет человека, а\nто, что исходит из уст, – вот, что оскверняет человека.","12":"Тогда подошли ученики и говорят Ему: знаешь\nли, что фарисеи, услышав это слово, соблазнились?","13":"Он же ответил: всякое растение, которое не Отец\nМой Небесный насадил, искоренится.","14":"Оставьте их, они слепые вожди слепых. Если же\nслепой ведет слепого, оба упадут в яму.","15":"И ответил Ему Петр: объясни нам притчу.","16":"Он же сказал: неужели и вы еще не разумеете?","17":"Не понимаете ли, что всё, входящее в уста, в\nчрево проходит и извергается вон?","18":"Исходящее же из уст – из сердца исходит, и оно\nоскверняет человека.","19":"Ибо из сердца исходят злые мысли, убийства,\nпрелюбодеяния,\nблудодеяния,\nкражи,\nлжесвидетельства, хулы.","20":"Это оскверняет человека; а есть неумытыми\nруками не оскверняет человека.","21":"И выйдя оттуда, Иисус удалился в пределы\nТирские и Сидонские.","22":"И вот, женщина Хананеянка, из той области,\nвышла и начала кричать: помилуй меня, Господи, Сын\nДавидов! Дочь мою жестоко мучит бес.","23":"Он же не ответил ей ни слова. И подойдя,\nученики Его просили Его: отпусти ее, потому что она\nкричит нам вслед.","24":"Но Он ответил: Я послан только к погибшим\nовцам дома Израилева.","25":"Она же, подойдя, кланялась Ему и говорила:\nГосподи, помоги мне.","26":"А Он ответил: нехорошо взять хлеб у детей и\nбросить собакам.","27":"Она же сказала: да, Господи, ведь и собаки едят\nот крошек, падающих со стола господ их.","28":"Тогда Иисус ответил ей: о женщина, велика твоя\nвера. Да будет тебе, как ты хочешь. И была исцелена\nдочь ее в час тот.","29":"И\nвыйдя\nоттуда,\nпришел\nИисус\nк\nморю\nГалилейскому и, поднявшись на гору, сидел там.","30":"И приступило к Нему множество народа с\nхромыми, слепыми, немыми, увечными и многими\nдругими. И повергли их к ногам Его, и Он исцелил их,","31":"так что удивился народ, видя, что немые\nговорят, увечные здоровы, хромые ходят, и слепые\nвидят, и прославил Бога Израилева.","32":"Иисус же, призвав учеников Своих, сказал им:\nжаль Мне народа: уже три дня остаются они со Мною, и\nнечего им есть; и отпустить их неевшими не хочу, чтобы\nне обессилели в дороге.","33":"И говорят Ему ученики: где нам взять столько\nхлебов в пустынном месте, чтобы накормить весь этот\nнарод?","34":"И говорит им Иисус: сколько у вас хлебов? Они\nже сказали: семь и немного рыбок.","35":"И повелев толпе возлечь на землю,","36":"взял эти семь хлебов и эти рыбы и, воздав\nблагодарение, преломил и давал ученикам, а ученики –\nнароду.","37":"И ели все, и насытились; и остававшихся кусков\nсобрали семь корзин полных.","38":"Евших же было четыре тысячи мужчин, кроме\nженщин и детей.","39":"И отпустив народ, Он вошел в лодку и прибыл в\nобласть Магдалинскую."},"16":{"1":"И подойдя, фарисеи и саддукеи, искушая Его,\nпросили показать им знамение с неба.","2":"Он же ответил им: вечером вы говорите: «вёдро,\nпотому что небо пылает»;","3":"и утром: «сегодня ненастье, потому что небо\nбагрово». О лице неба вы знаете, как судить, а о\nзнамениях времен не можете?","4":"Род лукавый и прелюбодейный знамения ищет, и\nне будет дано ему знамения, кроме знамения Ионы. И\nоставив их, отошел.","5":"И переправляясь на другую сторону, ученики\nзабыли взять хлебы.","6":"Иисус же сказал им: смотрите, берегитесь\nзакваски фарисейской и саддукейской.","7":"И они рассуждали про себя, говоря: мы хлебов не\nвзяли.","8":"Иисус узнал это и сказал: что рассуждаете про\nсебя, маловерные, что нет у вас хлебов?","9":"Еще ли не понимаете и не помните о пяти хлебах\nдля пяти тысяч, и сколько коробов вы набрали?","10":"о семи хлебах для четырех тысяч, и сколько\nкорзин вы набрали?","11":"Как вы не понимаете, что Я не о хлебах сказал:\n«берегитесь закваски фарисейской и саддукейской»?","12":"Тогда они уразумели, что Он сказал беречься не\nзакваски\nхлебной,\nно\nучения\nфарисейского\nи\nсаддукейского.","13":"А Иисус, придя в пределы Кесарии Филипповой,\nспрашивал учеников Своих говоря: за кого почитают\nлюди Сына Человеческого?","14":"Они сказали: одни за Иоанна Крестителя, другие\nза Илию, а иные за Иеремию или одного из пророков.","15":"Он говорит им: а вы за кого Меня почитаете?","16":"И ответил Симон Петр: Ты Христос, Сын Бога\nЖивого.","17":"И Иисус ему ответил: блажен ты, Симон Вар\nИона, потому что не плоть и кровь открыли тебе это, но\nОтец Мой, Который на небесах.","18":"И Я тебе говорю: ты Петр, и на этой скале Я\nпострою Мою Церковь, и врата ада не одолеют Ее.","19":"Я дам тебе ключи Царства Небесного; и что ты\nсвяжешь на земле, будет связано на небесах; и что ты\nразрешишь на земле, будет разрешено на небесах.","20":"Тогда Он повелел ученикам Своим никому не\nговорить, что Он Христос.","21":"С того времени начал Иисус Христос объяснять\nученикам Своим, что надлежит Ему идти в Иерусалим и\nмногое претерпеть от старейшин и первосвященников и\nкнижников, и быть убитым, и в третий день восстать.","22":"И отозвав Его, Петр начал Ему выговаривать: Бог\nмилостив к Тебе, Господи! Не будет этого с Тобой.","23":"Он же, обернувшись, сказал Петру: прочь! За\nМною, сатана! Ты соблазн Мне, потому что думаешь не о\nБожьем, но о человеческом.","24":"Тогда Иисус сказал ученикам Своим: если кто\nхочет за Мною пойти, да отречется от самого себя и\nвозьмет крест свой и следует за Мною.","25":"Ибо кто хочет душу свою спасти, тот погубит ее;\nкто же погубит душу свою ради Меня, тот найдет ее.","26":"Ибо что выгадает человек, если он весь мир\nприобретет, душе же своей повредит? Или что даст\nчеловек в обмен за душу свою?","27":"Ибо придет Сын Человеческий во славе Отца\nСвоего с ангелами Своими, и тогда воздаст каждому по\nделу его.","28":"Истинно говорю вам: есть некоторые из стоящих\nздесь, которые не вкусят смерти, доколе не увидят\nСына Человеческого, грядущего в Царстве Своем."},"17":{"1":"И через шесть дней берет Иисус Петра, Иакова и\nИоанна, брата его, и возводит их на гору высокую\nотдельно от других.","2":"И преобразился Он перед ними: и просияло лицо\nЕго как солнце, а одежды Его сделались белыми как\nсвет.","3":"И вот, явились им Моисей и Илия, беседующие с\nНим.","4":"Петр же сказал Иисусу: Господи, хорошо нам\nздесь быть. Если хочешь, сделаю здесь три шатра: Тебе\nодин, и Моисею один, и Илии один.","5":"Пока он еще говорил, вот, облако светлое осенило\nих, и вот, голос из облака говорит: это Сын Мой\nВозлюбленный, на Ком Мое благоволение; слушайте\nЕго.","6":"И услышав, ученики пали на лица свои и сильно\nиспугались.","7":"И подошел Иисус и, коснувшись их, сказал:\nвстаньте и не бойтесь.","8":"Подняв же глаза свои, они никого не увидели,\nкроме только Самого Иисуса.","9":"И когда сходили они с горы, заповедал им Иисус:\nникому не говорите об этом видении, доколе Сын\nЧеловеческий не восстанет из мертвых.","10":"И спросили Его ученики: что же книжники\nговорят, что Илии надлежит придти прежде?","11":"Он же ответил: Илия действительно придет и\nвосстановит всё:","12":"но говорю вам, что Илия уже пришел, и не узнали\nего, но сделали с ним всё, что им захотелось. Так и\nСыну Человеческому предстоит страдать от них.","13":"Тогда уразумели ученики, что Он сказал им об\nИоанне Крестителе.","14":"И когда пришли они к народу, подошел к Нему\nчеловек и, опускаясь перед Ним на колени,","15":"говорит: Господи, помилуй моего сына: он\nлунатик, и плохо ему; часто он бросается в огонь и\nчасто в воду.","16":"И привел я его к ученикам Твоим, и они не могли\nего исцелить.","17":"Иисус\nже\nответил:\nо\nрод\nневерный\nи\nразвращенный! Доколе буду с вами? Доколе буду\nвыносить вас? Приведите Мне его сюда,","18":"возбранил ему Иисус, и вышел из него бес, и был\nисцелен отрок в час тот.","19":"Тогда ученики подошли к Иисусу отдельно от\nдругих и сказали: почему мы не смогли изгнать его?","20":"Он же говорит им: по маловерию вашему; ибо\nистинно говорю вам: если будете иметь веру с зерно\nгорчичное, то скажете этой горе: «перейди отсюда\nтуда», и она перейдет; и ничего не будет невозможного\nдля вас.","21":"Стих 21 прежних русских переводов: «этот же\nрод изгоняется только молитвою и постом» встречается\nв Мк.9.29, и только в немногих рукописях Мф.","22":"Когда же они были вместе в Галилее, Иисус\nсказал им: будет предан Сын Человеческий в руки\nчеловеческие,","23":"и убьют Его, и в третий день Он восстанет. И они\nсильно опечалились.","24":"А когда они пришли в Капернаум, подошли к\nПетру сборщики дидрахм и сказали: Учитель ваш не\nвносит дидрахм?","25":"Он говорит: вносит. И когда он вошел в дом, то\nИисус предупредил его, сказав: как тебе кажется,\nСимон? Цари земные с кого берут пошлину или подать?\nС сынов ли своих, или с чужих?","26":"И когда он ответил: с чужих, то Иисус сказал\nему: значит, сыны свободны.","27":"Но чтобы нам не соблазнить их, пойди на море,\nзакинь уду, и первую рыбу, которая попадется, возьми;\nи открыв рот ее, найдешь статир; вынь его и дай им за\nМеня и за себя."},"18":{"1":"В тот час подошли ученики к Иисусу и спросили :\nкто же больше в Царстве Небесном?","2":"И подозвав дитя, Он поставил его посреди них","3":"и сказал: истинно говорю вам, если не обратитесь\nи не станете как дети, не войдете в Царство Небесное.","4":"Итак, кто смирит себя и будет как это дитя, тот и\nбольше в Царстве Небесном.","5":"И кто примет одно такое дитя во имя Мое, Меня\nпринимает.","6":"А кто соблазнит одного из малых сих, верующих в\nМеня, тому было бы лучше, если бы мельничный жернов\nповесили ему на шею и утопили его в пучине морской.","7":"Горе миру от соблазнов. Ибо нужно, чтобы пришли\nсоблазны; но горе тому человеку, чрез которого соблазн\nприходит.","8":"Если же рука твоя или нога твоя соблазняет тебя,\nотруби ее и брось ее от себя: лучше тебе войти в жизнь\nбез руки или без ноги, чем с двумя руками или с двумя\nногами быть ввергнутым в огонь вечный.","9":"И если глаз твой соблазняет тебя, вырви его и\nбрось от себя: лучше тебе кривым войти в жизнь, чем с\nдвумя глазами быть ввергнутым в геенну огненную.","10":"Смотрите, не пренебрегайте ни одним из малых\nсих. Говорю вам, что ангелы их на небесах непрестанно\nвидят лицо Отца Моего, Который на небесах.","11":"Стих 11 прежних русских переводов: «Ибо\nпришел\nСын\nЧеловеческий\nспасти\nпогибшее»\nвстречается в Лк.19.10. отсутствует в древнейших\nрукописях Мф.","12":"Как вам кажется? Если будет у некоего человека\nсто овец, и заблудится одна из них, не оставит ли он\nдевяноста девяти в горах, и не пойдет ли искать\nзаблудившуюся?","13":"И если случится найти ее, истинно говорю вам:\nон радуется о ней более, чем о девяноста девяти\nнезаблудившихся.","14":"Так нет воли Отца вашего, Который на небесах,\nчтобы погиб один из малых сих.","15":"Если же согрешит брат твой, иди, обличи его с\nглазу на глаз. Если он тебя послушает, приобрел ты\nбрата твоего.","16":"Если же не послушает, возьми с собой еще\nодного или двух, чтобы устами двух свидетелей или\nтрех подтвердилось каждое слово.","17":"Если же их не послушается, скажи церкви: а если\nне послушается и церкви, да будет тебе он, как язычник\nи мытарь.","18":"Истинно говорю вам: что свяжете на земле,\nбудет связано на небе; и что разрешите на земле, будет\nразрешено на небе.","19":"Еще говорю вам: если двое из вас согласятся на\nземле просить о чем-либо, будет им от Отца Моего,\nКоторый на небесах.","20":"Ибо, где двое или трое собраны во имя Мое, там\nЯ посреди них.","21":"Тогда подошел Петр и сказал Ему: Господи,\nсколько раз должен я прощать брату моему, если он\nбудет грешить против меня? До семи ли раз?","22":"Говорит ему Иисус: не говорю тебе: до семи, но\nдо семидесяти раз семи.","23":"Поэтому подобно Царство Небесное человеку\nцарю, который захотел сосчитаться со слугами своими;","24":"когда же начал он считаться, приведен был к\nнему один, который должен был десять тысяч талантов;","25":"а так как у него не было чем заплатить, то\nповелел господин продать его, и жену, и детей, и всё,\nчто у него было, и заплатить.","26":"Но слуга, павши ниц, поклонился ему и сказал:\n«потерпи на мне, и всё заплачу тебе».","27":"И пожалев слугу того, господин отпустил его и\nпростил ему долг.","28":"Но слуга тот, выйдя, нашел одного из товарищей\nсвоих по службе, который должен был ему сто динариев\nи, схватив его, душил, говоря: «заплати всё, что ты\nдолжен».","29":"Но товарищ его, павши ниц, просил его:\n«потерпи на мне и заплачу тебе».","30":"Он же не хотел, и пошел, и бросил его в тюрьму,\nпока не заплатит того, что должен.","31":"Товарищи его, увидев происшедшее, сильно\nопечалились, пришли и доложили господину своему о\nвсём происшедшем.","32":"Тогда, призвав его, господин говорит ему: «слуга\nлукавый, весь долг тот я простил тебе, потому что ты\nупросил меня;","33":"не надлежало ли и тебе помиловать товарища\nтвоего, как и я тебя помиловал?»","34":"И\nразгневавшись,\nгосподин\nпередал\nего\nистязателям, доколе не заплатит всего, что должен\nему.","35":"Так и Отец Мой Небесный поступит с вами, если\nвы не простите каждый от сердца брату своему."},"19":{"1":"И было: когда окончил Иисус слова эти, ушел Он\nиз Галилеи и пришел в область Иудеи по ту сторону\nИордана.","2":"И последовало за Ним много народа, и Он исцелил\nих там.","3":"И подошли к Нему фарисеи, искушая Его и\nспрашивая: по всякой ли причине можно отпускать\nжену свою?","4":"Он же ответил: разве вы не читали, что Создатель\nизначала «сотворил их мужчиною и женщиною»","5":"и сказал: «поэтому оставит человек отца и мать и\nприлепится к жене своей, и будут двое плотью\nединою»?","6":"Так что они уже не два, но плоть единая. Итак, что\nБог сочетал, того человек да не разлучает.","7":"Они говорят Ему: как же Моисей заповедал давать\nразводное свидетельство и отпускать?","8":"Он говорит им; Моисей по жестокосердию вашему\nпозволил вам отпускать жен ваших, изначала же не\nбыло установлено так.","9":"Говорю же вам: кто отпустит жену свою не по\nпричине блуда и женится на другой, прелюбодействует.","10":"Говорят Ему ученики: если так надлежит\nпоступать человеку с женой, лучше не жениться.","11":"Он же сказал им: не все вмещают слово это, но\nкому дано.","12":"Ибо есть скопцы, которые от чрева матери\nродились так; и есть скопцы, которые оскоплены были\nлюдьми; и есть скопцы, которые оскопили самих себя\nдля Царства Небесного. Могущий вместить да вместит.","13":"Тогда приведены были к Нему дети, чтобы Он\nвозложил на них руки и помолился; но ученики не\nпозволили им.","14":"Но\nИисус\nсказал:\nпустите\nдетей\nи\nне\nпрепятствуйте им приходить ко Мне: ибо таковых есть\nЦарство Небесное.","15":"И возложив на них руки, пошел оттуда.","16":"И вот, некто подошел к Нему и сказал: Учитель,\nчто мне сделать благого, чтобы получить жизнь\nвечную?","17":"Он же сказал ему: что ты Меня спрашиваешь о\nблагом? Есть один только Благой. Если же хочешь войти\nв жизнь, соблюдай заповеди.","18":"Говорит Ему: какие? Иисус же сказал: вот какие:\n«Не\nубивай,\nне\nпрелюбодействуй,\nне\nкради,\nне\nлжесвидетельствуй,","19":"почитай отца и мать; и возлюби ближнего твоего\nкак самого себя».","20":"Говорит Ему юноша: это всё я сохранил; чего еще\nнедостает мне?","21":"Сказал\nему\nИисус:\nесли\nхочешь\nбыть\nсовершенным, иди, продай имение твое и отдай нищим;\nи будешь иметь сокровище на небесах, и приходи,\nследуй за Мною.","22":"Услышав это, юноша ушел в печали, ибо владел\nон большим имуществом.","23":"Иисус же сказал ученикам Своим: истинно\nговорю вам: богатому трудно будет войти в Царство\nНебесное.","24":"И еще говорю вам: легче верблюду войти в\nигольное ушко, чем богатому в Царство Божие.","25":"Услышав,\nученики\nв\nсильном\nизумлении\nговорили: если так, кто же может быть спасен?","26":"Иисус\nвзглянул\nи\nсказал\nим:\nлюдям\nэто\nневозможно, Богу же всё возможно.","27":"Тогда ответил Ему Петр: вот мы оставили всё и\nпоследовали за Тобою; что же будет нам?","28":"И сказал им Иисус: истинно говорю вам, что вы,\nпоследовавшие за Мною, – в новом бытии, когда сядет\nСын Человеческий на престоле славы Своей, сядете и\nвы\nна\nдвенадцати\nпрестолах\nи\nбудете\nсудить\nдвенадцать колен Израилевых.","29":"И всякий, кто оставил дома, или братьев, или\nсестер, или отца, или мать, или детей, или земли, ради\nимени Моего, во сто раз больше получит и жизнь\nвечную наследует.","30":"Многие\nже\nбудут\nпервые\nпоследними\nи\nпоследние первыми."},"20":{"1":"Ибо Царство Небесное подобно человеку хозяину\nдома, который вышел рано утром нанять работников к\nсебе в виноградник.","2":"И согласившись с работниками по динарию в день,\nпослал их к себе в виноградник.","3":"И выйдя около третьего часа, увидел он других,\nпришедших и стоящих на площади без работы.","4":"Он и тем сказал: «идите и вы в виноградник мой, и\nчто будет справедливо, дам вам». И они пошли.","5":"Снова выйдя около шестого и девятого часа, он\nсделал так же.","6":"А выйдя около одиннадцатого часа, нашел других,\nпришедших и стоящих, и говорит им: «почему вы, придя\nсюда, стоите целый день без работы?»","7":"Они говорят ему: «потому что никто нас не\nнанял». Он говорит им: «идите и вы в виноградник».","8":"С наступлением же вечера говорит господин\nвиноградника управителю своему: «позови работников\nи выдай плату, начав с последних до первых».","9":"И нанятые около одиннадцатого часа пришли и\nполучили по динарию.","10":"Пришли и первые и подумали, что они получат\nбольше; но получили, как было условлено, по динарию и\nони;","11":"и получив, начали роптать на хозяина дома,","12":"говоря: «эти последние один час проработали, и\nты сравнял их с нами, перенесшими тягость дня и\nзной».","13":"Он же сказал одному из них в ответ: «друг, я не\nобижаю тебя; не за динарий ли ты согласился со мной?","14":"Возьми свое и иди; я же хочу этому последнему\nдать, как и тебе.","15":"Разве нельзя мне, как хочу, поступить с моим\nимуществом? Или глаз твой завистлив оттого, что я\nдобр?»","16":"Так\nбудут\nпоследние\nпервыми\nи\nпервые\nпоследними.","17":"И\nвосходя\nв\nИерусалим,\nИисус\nотозвал\nДвенадцать и в пути сказал им:","18":"вот,\nмы\nвосходим\nв\nИерусалим,\nи\nСын\nЧеловеческий\nпредан\nбудет\nпервосвященникам\nи\nкнижникам, и приговорят Его к смерти,","19":"и предадут Его язычникам на поругание и\nбичевание и распятие; и в третий день Он восстанет.","20":"Тогда подошла к Нему мать сыновей Зеведеевых\nс сыновьями своими, кланяясь и чего-то прося у Него.","21":"Он же сказал ей: чего ты хочешь? Она говорит\nЕму: скажи, чтобы сели эти два сына мои один по\nправую и другой по левую Твою сторону в Царстве\nТвоем.","22":"Иисус же ответил: не знаете, чего просите.\nМожете ли пить чашу, которую Я буду пить? Они\nговорят Ему: можем.","23":"Говорит им: пить Мою чашу будете, сесть же по\nправую Мою сторону и по левую – не Я даю, но кому\nуготовано Отцом Моим.","24":"И услышав, десять вознегодовали на двух\nбратьев.","25":"Иисус же, призвав их, сказал: вы знаете, что\nкнязья народов господствуют над ними, и вельможи\nпоказывают над ними свою власть.","26":"Между вами да не будет так, но кто хочет стать\nвеликим между вами, пусть будет вам слугою;","27":"и кто хочет между вами быть первым, пусть\nбудет вам рабом;","28":"как и Сын Человеческий не для того пришел,\nчтобы Ему послужили, но чтобы послужить и дать душу\nСвою как выкуп за многих.","29":"И когда выходили они из Иерихона, последовало\nза Ним много народа.","30":"И вот, двое слепых, сидевших у дороги, услышав,\nчто Иисус проходит, закричали: Господи, помилуй нас.\nСын Давидов!","31":"Народ же требовал от них, чтобы они замолчали;\nно те с еще большей силой закричали: Господи,\nпомилуй нас, Сын Давидов!","32":"И, остановившись, Иисус позвал их и сказал: что\nхотите, чтобы Я сделал вам?","33":"Они говорят Ему: Господи, чтобы открылись\nглаза наши.","34":"Сжалившись, Иисус коснулся их глаз, и они\nтотчас прозрели и последовали за Ним."},"21":{"1":"И когда они приблизились к Иерусалиму и пришли\nв Виффагию на горе Масличной, тогда Иисус послал\nдвух учеников","2":"и сказал им: идите в селение, которое напротив\nвас; и тотчас найдете ослицу привязанную и осленка с\nней; отвяжите и приведите Мне.","3":"И если кто скажет вам что-нибудь, вы ответите,\nчто они нужны Господу, и тотчас пошлет их.","4":"А произошло это, чтобы исполнилось сказанное\nчрез пророка:","5":"Скажите дочери Сиона: вот, Царь твой грядет к\nтебе, кроткий и воссевший на ослицу и на осленка, сына\nподъяремной.","6":"Ученики, отправившись и сделав, как повелел им\nИисус,","7":"привели ослицу и осленка и положили на них\nодежды, и Он сел поверх их.","8":"И очень многие в толпе разостлали свои одежды\nпо дороге, другие же резали ветви с деревьев и\nрасстилали по дороге;","9":"а народ, шедший впереди Его и следовавший за\nНим, восклицал: Осанна Сыну Давидову! Благословен\nГрядущий во имя Господне! Осанна в вышних!","10":"И когда вошел Он в Иерусалим, весь город\nпришел в движение, и говорили: кто это?","11":"Народ же говорил: это пророк Иисус из Назарета\nГалилейского.","12":"И вошел Иисус в храм, и изгнал всех продающих\nи покупающих в храме, и столы менял опрокинул и\nприлавки продающих голубей.","13":"И говорит им; написано: «Дом Мой домом\nмолитвы будет назван», вы же его делаете вертепом\nразбойников.","14":"И подошли к Нему слепые и хромые в храме, и Он\nисцелил их.","15":"А первосвященники и книжники, увидев дивные\nдела, которые Он совершил, и детей, восклицающих в\nхраме: Осанна Сыну Давидову! – вознегодовали","16":"и сказали Ему: слышишь Ты, что они говорят?\nИисус же ответил им: да! Разве вы никогда не читали:\n«Из уст младенцев и грудных детей Ты устроил Себе\nхвалу»?","17":"И оставив их, вышел из города в Вифанию и\nпровел там ночь.","18":"Утром же, возвращаясь в город, Он ощутил голод","19":"и, увидев при дороге одинокую смоковницу,\nподошел к ней и ничего не нашел на ней, кроме одних\nтолько листьев. И говорит ей: да не будет от тебя плода\nвовек. И смоковница сразу засохла.","20":"И увидев, ученики с удивлением говорили: как\nэто сразу засохла смоковница?","21":"Иисус же ответил им: истинно говорю вам: если\nбудете иметь веру и не усомнитесь, сделаете не только\nто, что было со смоковницей, но, если и горе этой\nскажете: «сойди с твоего места и бросься в море», –\nбудет.","22":"И всё, чего ни попросите в молитве с верою,\nполучите.","23":"И когда Он пришел в храм, подошли к Нему, пока\nОн учил, первосвященники и старейшины народа и\nспросили: какою властью Ты это делаешь, и кто Тебе\nдал эту власть?","24":"Иисус же ответил им: спрошу вас и Я об одном:\nесли скажете Мне, то и Я вам скажу, какою властью это\nделаю.","25":"Крещение Иоанново откуда было; с неба или от\nлюдей? Они же рассуждали между собой: если скажем:\n«с неба», Он скажет нам: «почему же вы не поверили\nему?»","26":"Если же скажем: «от людей», – боимся толпы,\nибо все считают Иоанна пророком.","27":"И они сказали Иисусу в ответ: не знаем. Сказал\nим и Он: и Я вам не скажу, какою властью это делаю.","28":"А как вам кажется? У человека было двое детей;\nи он, подойдя к первому, сказал: «Дитя мое, иди\nсегодня, работай в винограднике».","29":"Он же ответил: «Иду, господин», и не пошел.","30":"И подойдя ко второму, он сказал то же. И тот\nответил: «Не хочу», а после раскаялся и пошел.","31":"Кто из двух исполнил волю отца? Они говорят:\nпоследний. Говорит им Иисус: истинно говорю вам:\nмытари и блудницы идут впереди вас в Царство Божие.","32":"Ибо пришел к вам Иоанн путем праведности, и\nвы не поверили ему, а мытари и блудницы поверили\nему, вы же, увидев, не раскаялись и после, чтобы\nповерить ему.","33":"Выслушайте другую притчу. Был человек хозяин\nдома, который насадил виноградник и стеной его обнес,\nи выкопал в нем точило, и построил башню, и сдал его\nвиноградарям, и уехал.","34":"Когда же приблизилось время плодов, послал он\nсвоих рабов к виноградарям взять плоды свои;","35":"и взяли виноградари рабов его, кого прибили,\nкого убили, кого камнями побили.","36":"Снова послал он других рабов, в большем числе,\nчем первых: и поступили с ними так же.","37":"Наконец, послал он к ним сына своего, говоря:\n«Устыдятся сына моего».","38":"Виноградари же, увидев сына, сказали друг\nдругу: «Это наследник; давайте, убьем его и завладеем\nнаследством его».","39":"И взяв его, выбросили вон из виноградника и\nубили.","40":"Итак, когда придет господин виноградника, что\nсделает он с виноградарями теми?","41":"Говорят\nЕму:\nпредаст\nих,\nкак\nзлодеев,\nзаслуженной ими злой смерти и виноградник сдаст\nдругим виноградарям, которые будут отдавать ему\nплоды в свои сроки.","42":"Говорит им Иисус: никогда не читали вы в\nПисаниях: «Камень, который отвергли строители, он\nсделался главою угла: от Господа это, и удивительно в\nглазах наших»?","43":"Поэтому говорю вам: Царство Божие будет\nотнято у вас и дано приносящему его плоды народу;","44":"и тот, кто упадет на этот камень, разобьется: а\nна кого он упадет, того обратит в прах.","45":"И услышав притчи Его, первосвященники и\nфарисеи поняли, что Он говорит о них,","46":"и намеревались Его схватить, но побоялись\nнарода, так как Его почитали за пророка."},"22":{"1":"И снова Иисус обратился к ним в притчах:","2":"подобно\nЦарство\nНебесное\nчеловеку\nцарю,\nкоторый устроил брачный пир для сына своего","3":"и послал слуг своих позвать званных на брачный\nпир; и они не хотели придти.","4":"Снова послал других слуг, говоря: скажите\nзванным: «вот, обед мой я приготовил, быки мои и\nоткормленный скот заколоты, и всё готово; приходите\nна брачный пир».","5":"Они же, оставив его слова без внимания, ушли,\nкто – на свое поле, кто – на торговлю свою.","6":"Прочие же схватили слуг его, оскорбили и убили\nих.","7":"Разгневался царь и, послав войска свои, истребил\nубийц тех и город их сжег.","8":"Тогда говорит он слугам своим: «брачный пир\nготов, но званные не были достойны;","9":"идите же на концы улиц и, кого только найдете,\nзовите на брачный пир».","10":"И вышли слуги те на дороги и собрали всех, кого\nнашли: и злых и добрых; и наполнилась брачная палата\nвозлежащими.","11":"Вошел царь посмотреть на возлежащих и увидел\nтам человека, одетого не в брачную одежду,","12":"и говорит ему: «друг, как ты вошел сюда не в\nбрачной одежде?» Он же промолчал.","13":"Тогда царь сказал служителям: «свяжите ему\nноги и руки и выбросьте его во тьму внешнюю: там\nбудет плач и скрежет зубов».","14":"Ибо много званных, но мало избранных.","15":"Тогда фарисеи пошли и приняли решение\nуловить Его в слове.","16":"И посылают учеников своих с иродианами\nспросить Его: Учитель, мы знаем, что Ты истинен и пути\nБожию истинно учишь, и не считаешься ни с кем; ибо не\nсмотришь на лицо людей.","17":"Итак, скажи нам: как Тебе кажется? Можно\nплатить подать кесарю, или нет?","18":"Но Иисус, поняв их лукавство, сказал: что Меня\nискушаете, лицемеры?","19":"Покажите Мне монету, которою платится подать.\nОни же принесли Ему динарий.","20":"И говорит им: чье это изображение и надпись?","21":"Говорят: кесаря. Тогда говорит им: отдавайте же\nкесарево кесарю, а Божие – Богу.","22":"И услышав, они удивились и, оставив Его, ушли.","23":"В\nтот\nдень\nподошли\nк\nНему\nсаддукеи,\nутверждающие, что нет воскресения, и спросили Его:","24":"Учитель, Моисей сказал: «если кто умрет, не\nимея детей, то брат его пусть женится на жене его и\nвосстановит семя брату своему».","25":"Было же у нас семь братьев: и первый,\nженившись, скончался и, так как от него не было\nсемени, то жену свою он оставил брату своему;","26":"подобно и второй и третий, до семи;","27":"после же всех умерла жена.","28":"Итак, в воскресение, кого из семи будет она\nженой? Все, ведь, имели ее.","29":"Иисус же ответил им: вы заблуждаетесь, не зная\nПисаний, ни силы Божией.","30":"В воскресение не женятся, и замуж не выходят,\nно пребывают как ангелы на небе.","31":"А о воскресении мертвых неужели вы не читали\nсказанного вам Богом:","32":"«Я Бог Авраама, и Бог Исаака, и Бог Иакова»? Бог\n– не мертвых, но живых.","33":"И услышав, народ изумлялся учению Его.","34":"Фарисеи же, услышав, что Он заградил уста\nсаддукеям, собрались вокруг Него.","35":"И спросил один из них, законник, искушая Его:","36":"Учитель, какая заповедь большая в Законе?","37":"Он же сказал ему: «Возлюби Господа Бога твоего\nвсем сердцем твоим и всею душою твоею и всем\nразумом твоим»:","38":"это – большая и первая заповедь.","39":"Вторая подобна ей: «Возлюби ближнего твоего,\nкак самого себя».","40":"На этих двух заповедях держится весь Закон и\nПророки.","41":"Когда же собрались фарисеи, спросил их Иисус:","42":"Что вы думаете о Христе? Чей Он сын? Говорят\nЕму: Давидов.","43":"Говорит им: как же Давид в Духе называет Его\nГосподом, говоря:","44":"«Сказал Господь Господу моему: сядь по правую\nсторону Мою, доколе Я не положу врагов Твоих под ноги\nТвои»?","45":"Итак, если Давид называет Его Господом, как же\nОн сын его?","46":"И никто не мог ответить Ему. И с того дня никто\nуже не посмел задать Ему вопроса."},"23":{"1":"Тогда Иисус сказал толпе народа и ученикам\nСвоим:","2":"на\nМоисеевом\nседалище\nсели\nкнижники\nи\nфарисеи;","3":"итак всё, что они скажут вам, исполняйте и\nхраните, по делам же их не поступайте: ибо говорят они\nи не делают.","4":"Связывают они ноши тяжелые и неудобоносимые\nи возлагают на плечи людей, сами же и пальцем своим\nне хотят двинуть их.","5":"Все же дела свои совершают с тем, чтобы видели\nих люди; расширяют хранилища свои и увеличивают\nкисти;","6":"любят же первое место на званых обедах и первые\nсиденья в синагогах","7":"и приветствия на площадях, и чтобы звали их\nлюди: «равви!'","8":"Вас же пусть не называют равви, ибо один у вас\nУчитель, вы же все – братья.","9":"И отцом своим не называйте никого на земле, ибо\nодин у вас Отец – Небесный.","10":"И пусть не называют вас наставниками, потому\nчто Наставник у вас один: Христос.","11":"Больший из вас да будет вам слугою.","12":"Ибо, кто вознесет себя, тот смирён будет, а кто\nсмирит себя, тот вознесён будет.","13":"Горе вам, книжники и фарисеи, лицемеры, что\nзатворяете Царство Небесное перед людьми: вы и сами\nне входите и входящим не даете войти.","14":"Стих\n14\nпрежних\nрусских\nпереводов,\nвстречающийся в Мк.12.40 и Лк.20.47, отсутствует во\nвсех древнейших рукописях Мф.","15":"Горе вам, книжники и фарисеи, лицемеры, что\nобходите море и сушу, чтобы сделать хотя бы одного\nпрозелитом; и когда это случится, делаете его сыном\nгеенны вдвое худшим, чем вы.","16":"Горе вам, вожди слепые, говорящие: «кто\nпоклянется храмом – ничего, кто же поклянется золотом\nхрама – связан».","17":"Безумные и слепые, что же больше: золото, или\nхрам, освятивший золото?","18":"И: «кто поклянется жертвенником – ничего, кто\nже поклянется даром, который на нем – связан».","19":"Слепые! Что же больше: дар, или жертвенник,\nосвящающий дар?","20":"Итак, поклявшийся жертвенником клянется им и\nвсем, что на нем;","21":"и поклявшийся храмом клянется им и Живущим в\nнем;","22":"и\nпоклявшийся\nнебом\nклянется\nпрестолом\nБожиим и Сидящим на нем.","23":"Горе вам, книжники и фарисеи, лицемеры, что\nдаете десятину с мяты, аниса и тмина, и обошли более\nважное в Законе: правосудие и милосердие и верность;\nэто надлежало исполнить и того не опустить.","24":"Вожди\nслепые,\nоцеживающие\nкомара\nи\nпроглатывающие верблюда!","25":"Горе вам, книжники и фарисеи, лицемеры, что\nочищаете снаружи чашу и блюдо, внутри же они полны\nхищения и невоздержания.","26":"Фарисей слепой! Очисти прежде чашу и блюдо\nвнутри, чтобы и снаружи они стали чисты.","27":"Горе вам, книжники и фарисеи, лицемеры, что вы\nподобны гробницам побеленным, которые снаружи\nкажутся красивыми, внутри же полны костей мертвых и\nвсякой нечистоты.","28":"Так и вы снаружи кажетесь людям праведными,\nвнутри же наполнены лицемерием и беззаконием.","29":"Горе вам, книжники и фарисеи, лицемеры, что\nстроите гробницы пророков и украшаете памятники\nправедных","30":"и говорите: «если бы мы жили во дни отцов\nнаших, мы не были бы сообщниками их в крови\nпророков».","31":"Тем самым вы свидетельствуете против себя, что\nвы сыновья тех, которые убили пророков.","32":"Доведите же до полноты меру отцов ваших.","33":"Змеи, отродье змеиное! Как бежать вам от\nосуждения в геенну?","34":"Поэтому, вот, Я посылаю к вам пророков и\nмудрых и книжников; иных вы убьете и распнете, иных\nбудете бичевать в синагогах ваших и гнать из города в\nгород;","35":"да\nпридёт\nна\nвас\nвся\nкровь\nправедная,\nпроливаемая на земле, от крови Авеля праведного до\nкрови Захарии, сына Варахии, которого вы убили между\nхрамом и жертвенником.","36":"Истинно говорю вам: это всё придет на род этот.","37":"Иерусалим, Иерусалим, убивающий пророков и\nкамнями побивающий посланных к нему! Сколько раз\nхотел Я собрать детей твоих, как птица собирает\nптенцов под крылья, и вы не захотели!","38":"Вот, оставляется вам дом ваш пуст.","39":"Ибо говорю вам: не увидите Меня отныне, доколе\nне скажете: «Благословен Грядущий во имя Господне»."},"24":{"1":"И выйдя из храма, Иисус хотел идти, и подошли\nученики Его, чтобы показать Ему здания храма.","2":"А Он ответил: видите вы всё это? Истинно говорю\nвам: не останется здесь камня на камне, который не\nбудет опрокинут.","3":"Когда же сидел Он на горе Масличной, подошли к\nНему ученики отдельно от других и спросили Его: скажи\nнам, когда это будет, и какое знамение Твоего\nпришествия и конца века?","4":"И ответил им Иисус: смотрите, чтобы кто не ввел\nвас в заблуждение.","5":"Ибо многие придут под именем Моим, говоря: «я\nХристос», и многих введут в заблуждение.","6":"Предстоит же вам в будущем слышать о войнах и\nвоенных слухах. Смотрите, не ужасайтесь; ибо это\nдолжно произойти, но это еще не конец.","7":"Ибо восстанет народ на народ и царство на\nцарство, и будут голод и землетрясения по местам;","8":"всё же это начало мук рождения.","9":"Тогда будут предавать вас на страдание и будут\nубивать вас; и вы будете ненавидимы всеми народами\nза имя Мое.","10":"И тогда соблазнятся многие; и будут друг друга\nпредавать, и ненавидеть друг друга;","11":"и многие лжепророки восстанут и многих введут\nв заблуждение;","12":"от умножения беззакония, во многих охладеет\nлюбовь.","13":"Претерпевший же до конца, тот будет спасен.","14":"И будет проповедано это Евангелие Царства по\nвсей вселенной во свидетельство всем народам; и тогда\nпридет конец.","15":"Итак,\nкогда\nувидите\nмерзость\nзапустения,\nставшую на святом месте, о которой было сказано чрез\nДаниила пророка – читающий да разумеет, –","16":"тогда находящиеся в Иудее да бегут в горы;","17":"кто на крыше, да не спускается взять то, что в\nдоме его;","18":"и кто в поле, да не возвращается взять одежду\nсвою.","19":"Горе же имеющим во чреве и кормящим грудью в\nте дни.","20":"Молитесь, чтобы не случилось бегство ваше ни\nзимой, ни в субботу;","21":"ибо будет тогда великая скорбь, какой не было\nот начала мира доныне, и никогда не будет.","22":"И если бы не были сокращены дни те, не была бы\nспасена никакая плоть; но ради избранных будут\nсокращены дни те.","23":"Тогда, если кто вам скажет: «вот здесь Христос»,\nили: «там\"', – не верьте;","24":"ибо восстанут лжехристы и лжепророки и\nпроизведут знамения великие и чудеса, чтобы ввести в\nзаблуждение, если возможно, и избранных.","25":"Вот Я наперед сказал вам.","26":"Итак, если скажут вам: «вот Он в пустыне», – не\nвыходите; «вот Он во внутренних покоях», – не верьте;","27":"ибо, как молния исходит от востока и светит до\nзапада, так будет пришествие Сына Человеческого.","28":"Где будет труп, там соберутся орлы.","29":"Тотчас же, после скорби дней тех, солнце\nпомеркнет, и луна не даст света своего, и звезды\nупадут с неба, и силы небесные будут поколеблены.","30":"И тогда явится знамение Сына Человеческого на\nнебе; и тогда будут бить себя в грудь все племена\nземные и увидят Сына Человеческого, грядущего на\nоблаках небесных с силою и славою великою;","31":"и пошлет Он ангелов Своих с трубою великой, и\nсоберут избранных Его от четырех ветров, от края небес\nдо края их.","32":"А образом да будет вам смоковница: когда ветвь\nее становится уже мягкой и пускает листья, вы знаете,\nчто близко лето.","33":"Так и вы, когда увидите всё это, знайте, что\nблизко, при дверях.","34":"Истинно говорю вам: не пройдет род сей, доколе\nвсё это не сбудется.","35":"Небо и земля пройдут, слова же Мои не пройдут.","36":"О дне же том и часе никто не знает, ни ангелы\nнебесные, ни Сын, но один только Отец.","37":"Ибо как дни Ноя, так будет пришествие Сына\nЧеловеческого.","38":"Как во дни перед потопом ели и пили, женились\nи выходили замуж до того дня, как вошел Ной в ковчег,","39":"и не понимали, пока не пришел потоп и не унес\nвсех, – так будет и пришествие Сына Человеческого.","40":"Тогда будут двое в поле: один берется, а другой\nоставляется;","41":"две мелющие в жерновах: одна берется, а другая\nоставляется.","42":"Итак, бодрствуйте, ибо не знаете, в какой день\nГосподь ваш придет.","43":"Но вот, что вы знаете: если бы ведал хозяин\nдома, в какую стражу придет вор, он бодрствовал бы и\nне позволил бы подкопать дома своего.","44":"Поэтому и вы готовьтесь, ибо в час, в какой не\nдумаете, придет Сын Человеческий.","45":"Кто же верный раб и разумный, которого\nпоставил господин его над челядью своей, чтобы\nдавать им пищу вовремя?","46":"Блажен раб тот, которого господин его, придя,\nнайдет так поступающим.","47":"Истинно говорю вам: над всем имением своим\nпоставит его.","48":"Если же скажет злой раб тот в сердце своем:\n«медлит мой господин»,","49":"и начнет бить других рабов, таких же, как и он,\nесть же и пить с пьяницами, –","50":"придет господин раба того в день, в который он\nне ожидает, и в час, которого не знает,","51":"и рассечет его надвое и подвергнет его одной\nучасти с лицемерами: там будет плач и скрежет зубов."},"25":{"1":"Тогда подобно будет Царство Небесное десяти\nдевам,\nкоторые,\nвзяв\nсветильники\nсвои,\nвышли\nнавстречу жениху.","2":"Пять из них было неразумных, и пять разумных,","3":"Неразумные, взяв светильники свои, не взяли с\nсобой масла;","4":"разумные же взяли масло в сосудах, вместе со\nсветильниками своими.","5":"А пока жених медлил, все они задремали и уснули.","6":"В полночь же крик раздался: «вот жених,\nвыходите навстречу».","7":"Тогда встали все девы те и оправили светильники\nсвои.","8":"Неразумные же сказали разумным: «дайте нам от\nмасла вашего, ибо светильники наши гаснут».","9":"Но\nразумные\nответили,\nговоря:\"как\nбы\nне\nоказалось недостатка у нас и у вас. Пойдите лучше к\nпродавцам и купите себе».","10":"Пока же они ходили покупать, пришел жених, и\nготовые вошли вместе с ним на брачный пир, и дверь\nбыла затворена.","11":"После же приходят и прочие девы и говорят:\n«Господи! Господи! Отвори нам».","12":"Он же ответил: «Истинно говорю вам: не знаю\nвас».","13":"Итак, бодрствуйте, потому что не знаете ни дня,\nни часа.","14":"Ибо будет, как с человеком, который, уезжая,\nпозвал рабов своих и вручил им имение свое;","15":"и одному дал он пять талантов, другому два,\nиному один, каждому по его силе; и уехал.","16":"Тотчас пошел получивший пять талантов, вложил\nих в дело и приобрел другие пять;","17":"также получивший два приобрел другие два;","18":"получивший же один ушел, раскопал землю и\nскрыл деньги господина своего.","19":"По долгом же времени приходит господин рабов\nтех и сводит с ними счет.","20":"И подошел получивший пять талантов, принес\nдругие пять и сказал: «господин, пять талантов ты мне\nвручил; вот, другие пять талантов я приобрел».","21":"Сказал ему господин его: «хорошо, раб добрый и\nверный, в малом ты был верен, над многим тебя\nпоставлю; войди в радость господина твоего».","22":"Подошел и получивший два таланта и сказал:\n«господин, два таланта ты мне вручил; вот, другие два\nталанта я приобрел».","23":"Сказал ему господин его: «хорошо, раб добрый и\nверный, в малом ты был верен, над многим тебя\nпоставлю; войди в радость господина твоего».","24":"Подошел же и тот, у кого был один талант, и\nсказал: «господин, я знал тебя, что ты человек жёсткий:\nжнешь, где не сеял, и собираешь, где не рассыпал;","25":"и в страхе пошел и скрыл талант твой в земле:\nвот тебе твое».","26":"И ответил ему господин его: «лукавый раб и\nленивый, ты знал, что я жну, где не сеял, и собираю, где\nне рассыпал?","27":"Потому надлежало тебе дать деньги мои\nменялам, и придя, я получил бы свое с ростом.","28":"Возьмите же у него талант и дайте имеющему\nдесять талантов;","29":"ибо каждому имеющему будет дано, и у него\nбудет изобилие, а у неимеющего будет взято и то, что\nон имеет.","30":"И негодного раба выбросьте во тьму внешнюю:\nтам будет плач и скрежет зубов».","31":"Когда же придет Сын Человеческий во славе\nСвоей, и все ангелы с Ним, тогда сядет Он на престоле\nславы Своей,","32":"и будут собраны перед Ним все народы; и Он\nотделит их друг от друга, как пастух отделяет овец от\nкозлов;","33":"и поставит овец по правую Свою сторону, козлов\nже по левую.","34":"Тогда скажет Царь тем, кто по правую сторону\nЕго: «придите, благословенные Отца Моего, наследуйте\nЦарство, уготованное вам от основания мира.","35":"Ибо голоден был Я, и вы дали Мне есть; жаждал,\nи напоили Меня; странником был, и приняли Меня;","36":"наг, и одели Меня; болен был, и посетили Меня; в\nтюрьме был, и пришли ко Мне».","37":"Тогда ответят Ему праведные: «Господи, когда\nмы\nТебя\nвидели\nголодным,\nи\nнакормили?\nИли\nжаждущим, и напоили?","38":"Когда же мы видели Тебя странником, и\nприняли? Или нагим, и одели?","39":"Когда же мы видели Тебя больным, или в\nтюрьме, и пришли к Тебе?»","40":"И ответит им Царь: «истинно говорю вам: сделав\nдля одного из братьев Моих меньших, вы для Меня\nсделали».","41":"Тогда скажет и тем, кто по левую сторону:\n«идите\nот\nМеня,\nпроклятые,\nв\nогонь\nвечный,\nуготованный диаволу и ангелам его.","42":"Ибо голоден был Я, и вы не дали Мне есть;\nжаждал, и не напоили Меня;","43":"странником был, и не приняли Меня; наг, и не\nодели Меня; болен и в тюрьме, и не посетили Меня».","44":"Тогда ответят и они: «Господи, когда мы видели\nТебя голодным, или жаждущим, или странником, или\nнагим, или больным, или в тюрьме, и не послужили\nТебе?»","45":"Тогда Он ответит им: «Истинно говорю вам: не\nсделав для одного из этих меньших, вы и для Меня не\nсделали».","46":"И пойдут эти в муку вечную, праведные же в\nжизнь вечную."},"26":{"1":"И было: когда окончил Иисус все слова эти, сказал\nОн ученикам Своим:","2":"вы знаете, что через два дня Пасха, и Сын\nЧеловеческий предан будет на распятие.","3":"Тогда собрались первосвященники и старейшины\nнародные\nво\nдворец\nпервосвященника\nпо\nимени\nКаиафа,","4":"и сообща решили взять Иисуса хитростью и убить;","5":"но говорили: не в праздник, чтобы не произошло\nвозмущения в народе.","6":"Когда же Иисус был в Вифании, в доме Симона\nпрокаженного,","7":"подошла к Нему женщина с алебастровым сосудом\nмира драгоценного и стала возливать Ему на голову в\nто время, как Он возлежал.","8":"Увидев, ученики вознегодовали и говорили: к чему\nэта расточительность?","9":"Ведь можно было бы это продать за большую цену\nи дать нищим,","10":"Но Иисус, узнав, сказал им: что смущаете\nженщину? Доброе дело сделала она для Меня;","11":"ибо нищих вы всегда имеете с собою, Меня же не\nвсегда имеете;","12":"возлив это миро на тело Мое, она сделала это\nдля Моего погребения.","13":"Истинно говорю вам: где ни будет проповедано\nэто Евангелие, во всем мире, будут говорить и о том,\nчто сделала она, в воспоминание о ней.","14":"Тогда один из Двенадцати, по имени Иуда\nИскариот, пошел к первосвященникам","15":"и сказал им: что хотите дать мне, и я вам предам\nЕго? Они же отсчитали ему тридцать сребреников.","16":"И с того времени он искал удобного случая\nпредать Его.","17":"В первый же день опресноков подошли ученики к\nИисусу, говоря: где хочешь, чтобы мы приготовили Тебе\nвкусить Пасху?","18":"Он же сказал: идите в город к такому-то и\nскажите ему: «Учитель говорит: время Мое близко, у\nтебя Я совершу Пасху с учениками Моими».","19":"И сделали ученики, как повелел им Иисус, и\nприготовили Пасху.","20":"С\nнаступлением\nже\nвечера,\nОн\nвозлег\nс\nдвенадцатью учениками;","21":"и когда они ели, Он сказал: истинно говорю вам:\nодин из вас предаст Меня.","22":"И печалясь сильно, они начали говорить Ему,\nкаждый в отдельности: не я ли, Господи?","23":"Он же ответил: опустивший со Мною руку в\nблюдо, тот и предаст Меня.","24":"Впрочем Сын Человеческий идет, как написано о\nНем; но горе человеку тому, чрез которого Сын\nЧеловеческий предается: лучше было бы человеку тому\nне родиться.","25":"И сказал в ответ Иуда, предающий Его: не я ли,\nРавви? Говорит ему Иисус: ты сказал.","26":"И когда они ели, взял Иисус хлеб и, благословив,\nпреломил и, дав ученикам, сказал: возьмите, вкусите:\nэто есть тело Мое.","27":"И взяв чашу и возблагодарив, дал им и сказал:\nпейте из нее все;","28":"это есть кровь Моя нового завета, за многих\nизливаемая для отпущения грехов.","29":"Говорю же вам: не буду пить впредь от этого\nплода лозы виноградной до дня того, когда буду пить\nего новым вместе с вами в Царстве Отца Моего.","30":"И воспев хвалебную песнь, вышли они на гору\nМасличную.","31":"Тогда говорит им Иисус: все вы соблазнитесь из-\nза Меня в эту ночь, ибо написано: «Поражу пастыря, и\nбудут рассеяны овцы стада».","32":"По восстании же Моем Я предварю вас в Галилее.","33":"И ответил Ему Петр: если и все соблазнятся из-за\nТебя, я никогда не соблазнюсь.","34":"Сказал ему Иисус: истинно говорю тебе: в эту\nночь,\nпрежде\nчем\nпропоет\nпетух,\nты\nтрижды\nотречешься от Меня.","35":"Говорит Ему Петр: хотя бы надлежало мне\nвместе с Тобою умереть, не отрекусь от Тебя. Подобное\nже сказали и все ученики.","36":"Потом приходит с ними Иисус в местность,\nназываемую Гефсимания, и говорит ученикам: посидите\nздесь, а Я тем временем пойду туда и помолюсь.","37":"И\nвзяв\nс\nСобой\nПетра\nи\nобоих\nсыновей\nЗеведеевых, начал скорбеть и томиться.","38":"Тогда говорит им: объята скорбию душа Моя до\nсмерти, побудьте здесь и бодрствуйте со Мною.","39":"И пройдя немного вперед, пал на лицо Свое,\nмолился и говорил: Отче Мой, если возможно, да минует\nМеня чаша эта; впрочем, не как Я хочу, но как Ты.","40":"И приходит к ученикам, и находит их спящими, и\nговорит\nПетру:\nтак\nли\nне\nсмогли\nвы\nодин\nчас\nпободрствовать со Мною?","41":"Бодрствуйте и молитесь, чтобы не впасть вам в\nискушение: дух бодр, плоть же немощна.","42":"И снова, во второй раз, Он пошел и помолился\nтакими словами: Отче Мой, если не может чаша эта\nминовать Меня, чтобы Мне не пить ее, да будет воля\nТвоя.","43":"И придя снова, нашел их спящими: ибо их глаза\nотяжелели.","44":"И оставив их, Он снова отошел и помолился в\nтретий раз и снова сказал то же слово.","45":"Тогда приходит к ученикам и говорит им: что же,\nвы спите и почиваете? Вот, близок час, и Сын\nЧеловеческий предается в руки грешников.","46":"Вставайте, идем: вот, уже близко предающий\nМеня.","47":"И пока еще Он говорил, вот, пришел Иуда, один\nиз Двенадцати, и с ним большая толпа с мечами и\nкольями от первосвященников и старейшин народных.","48":"Предающий же дал им знак: кого я поцелую, Он\nи есть, возьмите Его.","49":"И тотчас подошел к Иисусу и сказал: здравствуй,\nРавви! и поцеловал Его.","50":"Иисус же сказал ему: друг, вот для чего ты\nздесь! Тогда они подошли, наложили руки на Иисуса и\nвзяли Его.","51":"И вот, один из бывших с Иисусом, протянув руку,\nвыхватил меч свой и, ударив раба первосвященника,\nотсек ему ухо.","52":"Тогда говорит ему Иисус: возврати меч твой в\nместо его, ибо все, взявшие меч, от меча погибнут.","53":"Или ты думаешь, что Я не могу упросить Отца\nМоего, и Он не даст Мне тотчас же более двенадцати\nлегионов ангелов?","54":"Как же исполнятся Писания, что это должно\nпроизойти?","55":"В тот час сказал Иисус народу: как на разбойника\nвышли вы с мечами и кольями задержать Меня; каждый\nдень сидел Я и учил в храме, и вы не взяли Меня.","56":"Это же всё произошло, чтобы исполнились\nписания пророков. Тогда все ученики, оставив Его,\nбежали.","57":"Взявшие же Иисуса отвели Его к Каиафе\nпервосвященнику,\nгде\nсобраны\nбыли\nкнижники\nи\nстарейшины.","58":"Петр же следовал за Ним издали, до двора\nпервосвященника; и войдя внутрь, сидел вместе со\nслужителями, чтобы видеть конец.","59":"Первосвященники же и синедрион в полном\nсоставе искали лжесвидетельства против Иисуса, чтобы\nпредать Его смерти.","60":"И\nне\nнашли,\nхотя\nи\nмного\nявилось\nлжесвидетелей. Наконец подошли двое","61":"и сказали: Он говорил: «Я могу разрушить храм\nБожий и в три дня воздвигнуть его».","62":"И встав, первосвященник сказал Ему: Ты ничего\nне отвечаешь? Что они против Тебя свидетельствуют?","63":"Иисус же молчал. И первосвященник сказал Ему:\nзаклинаю Тебя Богом Живым, скажи нам: Ты ли Христос,\nСын Божий?","64":"Говорит ему Иисус: ты сказал. Но Я говорю вам:\nотныне\nбудете\nвидеть\nСына\nЧеловеческого,\nвосседающего по правую сторону Силы и грядущего на\nоблаках небесных.","65":"Тогда первосвященник разодрал одежды свои и\nсказал: Он произнес хулу! Какая нам еще нужда в\nсвидетелях? Вот теперь вы слышали хулу!","66":"Как вам кажется? Они же ответили: повинен\nсмерти.","67":"Тогда плюнули Ему в лицо и заушили Его; другие\nже били Его,","68":"говоря: прореки нам, Христос, кто ударил Тебя?","69":"Петр же сидел снаружи, на дворе. И подошла к\nнему одна служанка и сказала: и ты был с Иисусом\nГалилеянином.","70":"Но он отрекся перед всеми и сказал: не знаю, что\nты говоришь.","71":"Когда же он прошел в ворота, увидела его\nдругая, и говорит находящимся там: этот был с Иисусом\nНазореем.","72":"И он снова отрекся с клятвой: я не знаю Этого\nЧеловека.","73":"Немного же спустя подошли стоявшие и сказали\nПетру: поистине и ты из них, ибо и говор твой обличает\nтебя.","74":"Тогда начал он усиленно клясться: я не знаю\nЭтого Человека. И тотчас пропел петух.","75":"И вспомнил Петр слово, сказанное Иисусом:\nпрежде чем пропоет петух, ты трижды отречешься от\nМеня. И выйдя вон, плакал горько."},"27":{"1":"А когда наступило утро, все первосвященники и\nстарейшины\nнародные,\nсобравшись,\nпостановили\nпредать Иисуса смерти.","2":"И\nсвязав\nЕго,\nотвели\nи\nпередали\nПилату,\nправителю.","3":"Тогда Иуда, предавший Его, увидев, что Он\nосужден, раскаялся и возвратил тридцать сребреников\nпервосвященникам и старейшинам,","4":"говоря: согрешил я, предав кровь невинную. Они\nже сказали: какое нам дело? Смотри сам.","5":"И бросив сребреники в храме, он ушел и\nповесился.","6":"Первосвященники же, взяв сребреники, сказали:\nнельзя вложить их в храмовую казну, так как это цена\nкрови.","7":"И\nприняв\nрешение,\nкупили\nна\nних\nполе\nгоршечника, как место погребения для чужестранцев.","8":"Потому и называется поле то Полем Крови до сего\nдня.","9":"Тогда исполнилось сказанное чрез Иеремию\nпророка:\nи\nвзяли\nтридцать\nсребреников,\nцену\nОцененного, Которого оценили сыны Израилевы,","10":"и дали их за поле горшечника, как повелел мне\nГосподь.","11":"Иисус же был поставлен перед правителем. И\nспросил Его правитель: Ты Царь Иудейский? Иисус же\nсказал: ты говоришь.","12":"На\nобвинение\nЕго\nпервосвященниками\nи\nстарейшинами Он ничего не ответил.","13":"Тогда говорит Ему Пилат: не слышишь, сколько\nпротив Тебя свидетельствуют?","14":"И Он не ответил ему ни на одно слово, так что\nправитель весьма удивлялся.","15":"На\nпраздник\nже\nимел\nправитель\nобычай\nотпускать в угоду народу одного узника, которого они\nхотели.","16":"Был тогда у них узник известный, по имени\nВаравва.","17":"Поэтому, когда они собрались, Пилат им сказал:\nкого хотите, чтобы я отпустил вам: Варавву, или Иисуса,\nназываемого Христом?","18":"Ибо он знал, что предали Его из зависти.","19":"И когда он сидел на судейском месте, жена его\nпослала ему сказать: не делай ничего Праведнику Тому!\nЯ сегодня в сновидении много пострадала из-за Него.","20":"Между тем первосвященники и старейшины\nубедили народ потребовать Варавву и погубить Иисуса.","21":"И ответил им правитель: кого из двоих хотите,\nчтобы я отпустил вам? Они сказали: Варавву.","22":"Говорит им Пилат: что же мне делать с Иисусом,\nназываемым Христом? Говорят все: да будет распят!","23":"Он сказал: какое же зло Он сделал? Но они еще\nсильнее кричали: да будет распят!","24":"Увидев же, что ничто не помогает, но даже\nначинается возмущение, Пилат взял воды, умыл руки\nперед\nнародом\nи\nсказал:\nневиновен\nя\nв\nкрови\nПраведника Этого, смотрите сами.","25":"И весь народ ответил: кровь Его на нас и на\nдетях наших.","26":"Тогда он отпустил им Варавву, Иисуса же по\nбичевании предал на распятие.","27":"Тогда воины правителя, взяв Иисуса в преторию,\nсобрали вокруг Него всю когорту","28":"и, раздев Его, надели на Него плащ алый;","29":"и сплетя венец из терния, возложили на голову\nЕго и вложили трость в правую руку Его и, преклонив\nперед Ним колени, надругались над Ним, говоря: да\nздравствует Царь Иудейский!","30":"И оплевав Его, взяли трость и били Его по голове.","31":"И когда надругались над Ним, сняли с Него\nплащ, и одели Его в одежды Его, и отвели Его на\nраспятие.","32":"Выходя же встретили они Киринеянина, по имени\nСимона; его и заставили взять крест Его.","33":"И придя на место, называемое Голгофа, что\nзначит Лобное место,","34":"дали Ему пить вина, смешанного с желчью; и\nотведав, Он не захотел пить.","35":"Распяв же Его, они разделили между собой\nодежды Его, бросая жребий;","36":"и, сидя, стерегли Его там.","37":"И\nпоставили\nнад\nголовой\nЕго\nнадпись\nс\nобозначением вины Его: Это – Иисус, Царь Иудейский.","38":"Тогда распинают с Ним двух разбойников: одного\nсправа, и другого слева.","39":"А прохожие хулили Его, кивая головами своими","40":"и говоря: Разрушающий храм и в три дня\nВоздвигающий! Спаси Себя Самого, если Ты Сын Божий,\nи сойди с креста.","41":"Подобным\nобразом\nи\nпервосвященники,\nиздеваясь вместе с книжниками и старейшинами,\nговорили:","42":"других спас, Себя Самого не может спасти! Он\nЦарь Израилев, пусть сойдет теперь с креста, и уверуем\nв Него;","43":"Он возложил упование на Бога; пусть избавит\nЕго теперь, если Он угоден Ему. Ибо сказал Он: «Я\nБожий Сын».","44":"Также и разбойники, распятые с Ним, поносили\nЕго.","45":"От шестого же часа тьма наступила по всей\nземле до часа девятого.","46":"А около девятого часа возопил Иисус громким\nголосом: Или, Или! лама савахфани? то есть: Боже Мой,\nБоже Мой! Для чего Ты Меня оставил?","47":"Некоторые же из стоявших там, услышав,\nсказали: Илию зовет Он.","48":"И тотчас побежал один из них, взял губку,\nнаполнил уксусом и, наткнув на трость, давал Ему пить.","49":"Прочие же сказали: оставь; посмотрим, придет\nли Илия, чтобы спасти Его.","50":"Иисус же снова возопил громким голосом и отдал\nдух.","51":"И вот, завеса храма разорвалась сверху донизу\nнадвое; и земля потряслась; и камни расселись;","52":"и гробницы открылись; и многие тела усопших\nсвятых восстали;","53":"и выйдя из гробниц по восстании Его, вошли они\nв святой город и явились многим.","54":"Сотник же и вместе с ним стерегущие Иисуса,\nувидев\nземлетрясение\nи\nвсё\nпроисходящее,\nустрашились сильно, говоря: воистину был Он Божий\nСын.","55":"И\nмного\nженщин\nсмотрело\nиздали.\nОни\nпоследовали за Иисусом из Галилеи, служа Ему;","56":"между ними были Мария Магдалина и Мария,\nмать Иакова и Иосифа, и мать сыновей Зеведеевых.","57":"С наступлением же вечера пришел богатый\nчеловек из Аримафеи, именем Иосиф, который и сам\nбыл учеником Иисуса;","58":"явившись к Пилату, он попросил тело Иисуса.\nТогда Пилат повелел его выдать.","59":"И взяв тело, Иосиф обернул его в чистое полотно","60":"и положил в новой своей гробнице, которую он\nвысек в скале, и, привалив большой камень ко входу\nгробницы, ушел.","61":"А Мария Магдалина и другая Мария сидели там\nнапротив гробницы.","62":"На другой же день, который приходится после\nпятницы, собрались первосвященники и фарисеи к\nПилату","63":"и\nсказали:\nгосподин,\nмы\nвспомнили,\nчто\nобманщик тот сказал, еще будучи в живых: «через три\nдня восстану».","64":"Повели поэтому охранять гробницу до третьего\nдня, чтобы ученики придя не украли Его, и не сказали\nбы народу: «восстал из мертвых»; и будет последний\nобман хуже первого.","65":"Сказал\nим\nПилат:\nимеете\nстражу;\nидите,\nохраняйте, как знаете.","66":"И они пошли и охраняли гробницу, запечатав\nкамень и приставив стражу."},"28":{"1":"По прошествии же субботы, на рассвете первого\nдня недели, пришла Мария Магдалина и другая Мария\nпосмотреть могилу.","2":"И вот, произошло великое землетрясение, ибо\nангел Господень, сойдя с неба и подойдя, отвалил\nкамень и сидел на нем.","3":"Был же вид его как молния, и одежда его бела как\nснег.","4":"Страхом перед ним были потрясены стерегущие и\nстали как мертвые.","5":"И заговорил ангел и сказал женщинам: не\nбойтесь; я знаю, что вы Иисуса распятого ищете.","6":"Его нет здесь: ибо восстал Он, как сказал.\nПодойдите, посмотрите место, где Он лежал,","7":"и идите скорее, скажите ученикам Его, что Он\nвосстал из мертвых, и вот, Он предваряет вас в\nГалилее; там вы Его увидите. Вот, я сказал вам.","8":"И уйдя скоро от гробницы, со страхом и радостью\nвеликой побежали они возвестить ученикам Его.","9":"И вот, Иисус встретил их и сказал: радуйтесь. Они\nже, подойдя, ухватились за ноги Его и поклонились Ему.","10":"Тогда говорит им Иисус: не бойтесь; идите,\nвозвестите братьям Моим, чтобы шли в Галилею, и там\nони Меня увидят.","11":"Когда же они шли, некоторые из стражи пришли\nв\nгород\nи\nвозвестили\nпервосвященникам\nо\nвсём\nпроисшедшем.","12":"И они, собравшись со старейшинами и приняв\nрешение, дали воинам достаточно денег,","13":"говоря: скажите: «ученики Его, придя ночью,\nукрали Его, пока мы спали».","14":"И если это станет известно у правителя, мы\nуладим дело и избавим вас от неприятностей.","15":"Они же, взяв деньги, поступили, как были\nнаучены. И слово это было разглашено среди Иудеев до\nсего дня.","16":"Одиннадцать\nже\nучеников\nотправились\nв\nГалилею на гору, куда повелел им Иисус.","17":"И,\nувидев\nЕго,\nпоклонились;\nдругие\nже\nусомнились.","18":"И подойдя, Иисус сказал им: дана Мне всякая\nвласть на небе и на земле.","19":"Итак, идите, научите все народы, крестя людей\nво имя Отца и Сына и Святого Духа,","20":"уча их соблюдать всё, что Я заповедал вам. И\nвот, Я с вами все дни до конца века."}};
